window.GENERATED_MODULES.push(.../*__DATA_START__*/[{"id":"gen-gk-current-affairs-2026-09-05-mto4gtwc","subject":"gk","day":0,"level":1,"title":"Current Affairs","hi":"समसामयिकी","concepts":[{"title":"Recent Events and Developments","title_hi":"हाल की घटनाएं और विकास","simple":"Current affairs are important recent events happening around the world.","simple_hi":"समसामयिकी का मतलब है दुनिया में हाल ही में होने वाली महत्वपूर्ण घटनाएं।","intro":"","points":["Current affairs include news about politics, sports, science, and more. (समसामयिकी में राजनीति, खेल, विज्ञान आदि की खबरें शामिल हैं।)","They help us stay informed and are often asked in exams. (इनसे हमें जानकारी मिलती है और परीक्षाओं में अक्सर पूछा जाता है।)","Important dates, awards, and appointments are common topics. (महत्वपूर्ण तिथियाँ, पुरस्कार और नियुक्तियाँ सामान्य विषय हैं।)","Current affairs change daily, so regular reading is needed. (समसामयिकी प्रतिदिन बदलती है, इसलिए नियमित पढ़ना आवश्यक है।)"],"example":"For example, if India wins a cricket match, that is current affairs. Similarly, if a new chief minister is sworn in, that is also current affairs. (उदाहरण के लिए, अगर भारत क्रिकेट मैच जीतता है, तो वह समसामयिकी है। इसी तरह, अगर कोई नया मुख्यमंत्री शपथ लेता है, तो वह भी समसामयिकी है।)","trick":"Remember 'CA' as 'Current Affairs' – like a daily newspaper. (CA को 'Current Affairs' के रूप में याद रखें – जैसे दैनिक समाचार पत्र।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In exams, current affairs questions often come from the last 6 months. So, focus on recent major events, government schemes, and international summits. Also, note that some questions may be based on static events like important days. (परीक्षाओं में, समसामयिकी के प्रश्न अक्सर पिछले 6 महीनों से आते हैं। इसलिए, हाल की प्रमुख घटनाओं, सरकारी योजनाओं और अंतरराष्ट्रीय शिखर सम्मेलनों पर ध्यान दें। साथ ही, कुछ प्रश्न स्थिर घटनाओं जैसे महत्वपूर्ण दिनों पर आधारित हो सकते हैं।)","body_hi":"In exams, current affairs questions often come from the last 6 months. So, focus on recent major events, government schemes, and international summits. Also, note that some questions may be based on static events like important days. (परीक्षाओं में, समसामयिकी के प्रश्न अक्सर पिछले 6 महीनों से आते हैं। इसलिए, हाल की प्रमुख घटनाओं, सरकारी योजनाओं और अंतरराष्ट्रीय शिखर सम्मेलनों पर ध्यान दें। साथ ही, कुछ प्रश्न स्थिर घटनाओं जैसे महत्वपूर्ण दिनों पर आधारित हो सकते हैं।)"}}],"questions":[{"q":"Who is the current Chief Minister of Uttar Pradesh as of September 2026?","q_hi":"सितंबर 2026 तक उत्तर प्रदेश के मुख्यमंत्री कौन हैं?","o":["Yogi Adityanath","Akhilesh Yadav","Mayawati","Rahul Gandhi"],"o_hi":["योगी आदित्यनाथ","अखिलेश यादव","मायावती","राहुल गांधी"],"a":0,"exp":"Yogi Adityanath is the Chief Minister of Uttar Pradesh since 2017.","exp_hi":"योगी आदित्यनाथ 2017 से उत्तर प्रदेश के मुख्यमंत्री हैं।","why":["Akhilesh Yadav was CM from 2012 to 2017, not now.","Mayawati was CM earlier, not now.","Rahul Gandhi is a Member of Parliament, not CM."],"topic":"State Government","level":1,"mode":"standard"},{"q":"Which country hosted the 2026 FIFA World Cup?","q_hi":"2026 फीफा विश्व कप की मेजबानी किस देश ने की?","o":["USA, Canada and Mexico","Qatar","Russia","Brazil"],"o_hi":["अमेरिका, कनाडा और मैक्सिको","कतर","रूस","ब्राज़ील"],"a":0,"exp":"The 2026 FIFA World Cup is being hosted by the United States, Canada, and Mexico.","exp_hi":"2026 फीफा विश्व कप की मेजबानी संयुक्त राज्य अमेरिका, कनाडा और मैक्सिको द्वारा की जा रही है।","why":["Qatar hosted the 2022 World Cup.","Russia hosted the 2018 World Cup.","Brazil hosted the 2014 World Cup."],"topic":"Sports","level":1,"mode":"standard"},{"q":"What is the theme of World Environment Day 2026?","q_hi":"विश्व पर्यावरण दिवस 2026 की थीम क्या है?","o":["Land Restoration, Desertification and Drought Resilience","Beat Plastic Pollution","Air Pollution","Biodiversity"],"o_hi":["भूमि बहाली, मरुस्थलीकरण और सूखा सहनशीलता","प्लास्टिक प्रदूषण को हराएं","वायु प्रदूषण","जैव विविधता"],"a":0,"exp":"The theme for World Environment Day 2026 is 'Land Restoration, Desertification and Drought Resilience'.","exp_hi":"विश्व पर्यावरण दिवस 2026 की थीम 'भूमि बहाली, मरुस्थलीकरण और सूखा सहनशीलता' है।","why":["Beat Plastic Pollution was the theme for 2023.","Air Pollution was the theme for 2019.","Biodiversity was the theme for 2020."],"topic":"Environment","level":2,"mode":"standard"},{"q":"Who was awarded the Bharat Ratna in 2026?","q_hi":"2026 में भारत रत्न किसे प्रदान किया गया?","o":["Lata Mangeshkar","Sachin Tendulkar","M. S. Swaminathan","Pranab Mukherjee"],"o_hi":["लता मंगेशकर","सचिन तेंदुलकर","एम. एस. स्वामीनाथन","प्रणब मुखर्जी"],"a":2,"exp":"M. S. Swaminathan, known as the father of India's Green Revolution, was awarded the Bharat Ratna in 2026.","exp_hi":"भारत के हरित क्रांति के जनक कहे जाने वाले एम. एस. स्वामीनाथन को 2026 में भारत रत्न प्रदान किया गया।","why":["Lata Mangeshkar received Bharat Ratna in 2001.","Sachin Tendulkar received Bharat Ratna in 2014.","Pranab Mukherjee received Bharat Ratna in 2019."],"topic":"Awards","level":2,"mode":"standard"},{"q":"Which Indian state launched the 'Mukhyamantri Yuva Udyami Yojana' in 2026?","q_hi":"2026 में किस भारतीय राज्य ने 'मुख्यमंत्री युवा उद्यमी योजना' शुरू की?","o":["Uttar Pradesh","Bihar","Madhya Pradesh","Rajasthan"],"o_hi":["उत्तर प्रदेश","बिहार","मध्य प्रदेश","राजस्थान"],"a":0,"exp":"Uttar Pradesh launched the 'Mukhyamantri Yuva Udyami Yojana' in 2026 to promote entrepreneurship among youth.","exp_hi":"उत्तर प्रदेश ने युवाओं में उद्यमिता को बढ़ावा देने के लिए 2026 में 'मुख्यमंत्री युवा उद्यमी योजना' शुरू की।","why":["Bihar has its own schemes but not this one.","Madhya Pradesh has different schemes.","Rajasthan has different schemes."],"topic":"Government Schemes","level":2,"mode":"standard"},{"q":"What is the currency of the newly formed country 'XYZ' (fictional) in 2026?","q_hi":"2026 में नए बने देश 'XYZ' (काल्पनिक) की मुद्रा क्या है?","o":["Dinar","Rupee","Peso","Crown"],"o_hi":["दीनार","रुपया","पेसो","क्राउन"],"a":0,"exp":"This is a hypothetical question; in reality, no such country exists. In exams, such questions are not asked. But for practice, we assume the currency is Dinar.","exp_hi":"यह एक काल्पनिक प्रश्न है; वास्तव में ऐसा कोई देश मौजूद नहीं है। परीक्षाओं में ऐसे प्रश्न नहीं पूछे जाते। लेकिन अभ्यास के लिए, हम मान लेते हैं कि मुद्रा दीनार है।","why":["Rupee is used in India and some other countries.","Peso is used in many Latin American countries.","Crown is used in some European countries."],"topic":"International Affairs","level":3,"mode":"standard"}]},{"id":"gen-gk-indian-polity-governance-mto4h7p9","subject":"gk","day":0,"level":1,"title":"Indian Polity & Governance","hi":"भारतीय राजनीति एवं शासन व्यवस्था","concepts":[{"title":"Key Features of Indian Polity","title_hi":"भारतीय राजनीति की प्रमुख विशेषताएँ","simple":"India is a democratic country where the people elect their leaders.","simple_hi":"भारत एक लोकतांत्रिक देश है जहाँ लोग अपने नेताओं को चुनते हैं।","intro":"","points":["भारत का संविधान 26 नवंबर 1949 को बना और 26 जनवरी 1950 से लागू हुआ। (The Indian Constitution was made on 26 Nov 1949 and came into force on 26 Jan 1950.)","भारत एक संसदीय प्रणाली है, जहाँ प्रधानमंत्री सरकार का प्रमुख होता है। (India has a parliamentary system where the Prime Minister is the head of government.)","राष्ट्रपति देश का प्रथम नागरिक और संवैधानिक प्रमुख होता है। (The President is the first citizen and constitutional head of the country.)","संविधान में मौलिक अधिकार (Fundamental Rights) नागरिकों को दिए गए हैं। (The Constitution grants Fundamental Rights to citizens.)","भारत में तीन स्तर की सरकारें हैं: केंद्र, राज्य और स्थानीय। (India has three levels of government: central, state, and local.)"],"example":"जैसे हमारे विद्यालय में प्रधानाचार्य (Principal) होते हैं, वैसे ही देश में राष्ट्रपति होते हैं। लेकिन असली काम प्रधानमंत्री (Prime Minister) और मंत्री (Ministers) करते हैं, जैसे विद्यालय में उप-प्रधानाचार्य और शिक्षक। (Just as a school has a Principal, the country has a President. But the real work is done by the Prime Minister and Ministers, like the Vice-Principal and teachers.)","trick":"याद रखें: 'संसद' = सोचो + समझो + कानून बनाओ। (Remember: 'Parliament' = Think + Discuss + Make laws.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"भारत का संविधान विश्व का सबसे लंबा लिखित संविधान है। इसमें संघीय ढाँचा (federal structure) है, लेकिन केंद्र सरकार को अधिक शक्तियाँ दी गई हैं। यह 'संघीय व्यवस्था' और 'एकात्मक भावना' का मिश्रण है। (India's Constitution is the world's longest written constitution. It has a federal structure but gives more powers to the central government. It is a mix of federal system and unitary spirit.)","body_hi":"भारत का संविधान विश्व का सबसे लंबा लिखित संविधान है। इसमें संघीय ढाँचा (federal structure) है, लेकिन केंद्र सरकार को अधिक शक्तियाँ दी गई हैं। यह 'संघीय व्यवस्था' और 'एकात्मक भावना' का मिश्रण है। (India's Constitution is the world's longest written constitution. It has a federal structure but gives more powers to the central government. It is a mix of federal system and unitary spirit.)"}}],"questions":[{"q":"Who is the constitutional head of the Indian government?","q_hi":"भारतीय सरकार का संवैधानिक प्रमुख कौन होता है?","o":["Prime Minister","President","Chief Justice of India","Vice President"],"o_hi":["प्रधानमंत्री","राष्ट्रपति","भारत के मुख्य न्यायाधीश","उपराष्ट्रपति"],"a":1,"exp":"The President is the constitutional head of the Indian government, while the Prime Minister is the executive head.","exp_hi":"राष्ट्रपति भारतीय सरकार का संवैधानिक प्रमुख है, जबकि प्रधानमंत्री कार्यपालिका का प्रमुख होता है।","why":["प्रधानमंत्री सरकार का वास्तविक प्रमुख होता है, लेकिन संवैधानिक प्रमुख नहीं।","मुख्य न्यायाधीश न्यायपालिका का प्रमुख होता है, सरकार का नहीं।","उपराष्ट्रपति राज्यसभा का सभापति होता है, संवैधानिक प्रमुख नहीं।"],"topic":"Indian Polity","level":1,"mode":"standard"},{"q":"Which of the following is a Fundamental Right guaranteed by the Indian Constitution?","q_hi":"निम्नलिखित में से कौन सा भारतीय संविधान द्वारा प्रदत्त मौलिक अधिकार है?","o":["Right to Property","Right to Equality","Right to Work","Right to Free Education"],"o_hi":["संपत्ति का अधिकार","समानता का अधिकार","काम का अधिकार","निःशुल्क शिक्षा का अधिकार"],"a":1,"exp":"Right to Equality is a Fundamental Right under Article 14-18. Right to Property was removed from Fundamental Rights by the 44th Amendment.","exp_hi":"समानता का अधिकार अनुच्छेद 14-18 के अंतर्गत मौलिक अधिकार है। संपत्ति का अधिकार 44वें संशोधन द्वारा मौलिक अधिकारों से हटा दिया गया।","why":["संपत्ति का अधिकार अब मौलिक अधिकार नहीं है, यह कानूनी अधिकार है।","काम का अधिकार मौलिक अधिकार नहीं है, यह नीति-निर्देशक सिद्धांत है।","निःशुल्क शिक्षा का अधिकार 6-14 वर्ष के बच्चों के लिए है, लेकिन यह अनुच्छेद 21A में है, जो मौलिक अधिकार है, लेकिन 'Right to Free Education' सही नाम नहीं है।"],"topic":"Fundamental Rights","level":1,"mode":"standard"},{"q":"The Constitution of India was adopted on which date?","q_hi":"भारतीय संविधान किस तिथि को अपनाया गया था?","o":["26 January 1950","15 August 1947","26 November 1949","2 October 1948"],"o_hi":["26 जनवरी 1950","15 अगस्त 1947","26 नवंबर 1949","2 अक्टूबर 1948"],"a":2,"exp":"The Constitution was adopted on 26 November 1949, and it came into effect on 26 January 1950.","exp_hi":"संविधान 26 नवंबर 1949 को अपनाया गया था और 26 जनवरी 1950 को लागू हुआ।","why":["26 जनवरी 1950 वह तारीख है जब संविधान लागू हुआ था, न कि अपनाया गया था।","15 अगस्त 1947 भारत की स्वतंत्रता की तारीख है।","2 अक्टूबर 1948 महात्मा गांधी की जयंती है, संविधान से संबंधित नहीं।"],"topic":"Constitution","level":1,"mode":"standard"},{"q":"Which of the following is NOT a feature of the Indian Constitution?","q_hi":"निम्नलिखित में से कौन सा भारतीय संविधान की विशेषता नहीं है?","o":["Parliamentary system","Federal system","Presidential system","Independent judiciary"],"o_hi":["संसदीय प्रणाली","संघीय प्रणाली","राष्ट्रपति प्रणाली","स्वतंत्र न्यायपालिका"],"a":2,"exp":"India follows a parliamentary system, not a presidential system. In a presidential system, the President is both head of state and government.","exp_hi":"भारत संसदीय प्रणाली का पालन करता है, राष्ट्रपति प्रणाली का नहीं। राष्ट्रपति प्रणाली में राष्ट्रपति राज्य और सरकार दोनों का प्रमुख होता है।","why":["संसदीय प्रणाली भारत की विशेषता है, इसलिए यह गलत नहीं है।","संघीय प्रणाली भारत में है, इसलिए यह गलत नहीं है।","स्वतंत्र न्यायपालिका भारत में है, इसलिए यह गलत नहीं है।"],"topic":"Constitution Features","level":1,"mode":"standard"},{"q":"Who appoints the Prime Minister of India?","q_hi":"भारत के प्रधानमंत्री की नियुक्ति कौन करता है?","o":["President","Vice President","Lok Sabha Speaker","Chief Justice of India"],"o_hi":["राष्ट्रपति","उपराष्ट्रपति","लोकसभा अध्यक्ष","भारत के मुख्य न्यायाधीश"],"a":0,"exp":"The President appoints the Prime Minister. Usually, the leader of the majority party in Lok Sabha is appointed.","exp_hi":"राष्ट्रपति प्रधानमंत्री की नियुक्ति करता है। आमतौर पर लोकसभा में बहुमत दल का नेता नियुक्त किया जाता है।","why":["उपराष्ट्रपति प्रधानमंत्री की नियुक्ति नहीं करता।","लोकसभा अध्यक्ष सदन का पीठासीन अधिकारी होता है।","मुख्य न्यायाधीश न्यायपालिका का प्रमुख होता है।"],"topic":"Executive","level":1,"mode":"standard"},{"q":"Which article of the Indian Constitution deals with the Right to Constitutional Remedies?","q_hi":"भारतीय संविधान का कौन सा अनुच्छेद संवैधानिक उपचारों के अधिकार से संबंधित है?","o":["Article 32","Article 21","Article 14","Article 19"],"o_hi":["अनुच्छेद 32","अनुच्छेद 21","अनुच्छेद 14","अनुच्छेद 19"],"a":0,"exp":"Article 32 gives the right to move the Supreme Court for enforcement of Fundamental Rights. Dr. Ambedkar called it the 'heart and soul' of the Constitution.","exp_hi":"अनुच्छेद 32 मौलिक अधिकारों के प्रवर्तन के लिए उच्चतम न्यायालय जाने का अधिकार देता है। डॉ. आंबेडकर ने इसे संविधान की 'आत्मा' कहा।","why":["अनुच्छेद 21 जीवन और व्यक्तिगत स्वतंत्रता का अधिकार है।","अनुच्छेद 14 समानता का अधिकार है।","अनुच्छेद 19 स्वतंत्रता के अधिकार से संबंधित है।"],"topic":"Fundamental Rights","level":2,"mode":"standard"}]},{"id":"gen-gk-science-technology-space-defence-it-mto4houy","subject":"gk","day":0,"level":1,"title":"Science & Technology: Space, Defence, IT","hi":"विज्ञान और प्रौद्योगिकी: अंतरिक्ष, रक्षा, सूचना प्रौद्योगिकी","concepts":[{"title":"Key Developments in Space, Defence, and IT","title_hi":"अंतरिक्ष, रक्षा और सूचना प्रौद्योगिकी में प्रमुख विकास","simple":"Science and technology helps us explore space, protect our country, and use computers.","simple_hi":"विज्ञान और प्रौद्योगिकी हमें अंतरिक्ष की खोज, देश की रक्षा और कंप्यूटर के उपयोग में मदद करती है।","intro":"","points":["ISRO is India's space agency; it launched Chandrayaan and Mangalyaan. (इसरो भारत की अंतरिक्ष एजेंसी है; इसने चंद्रयान और मंगलयान लॉन्च किए।)","India's first satellite was Aryabhata (1975). (भारत का पहला उपग्रह आर्यभट्ट (1975) था।)","Agni and Prithvi are India's missile systems. (अग्नि और पृथ्वी भारत की मिसाइल प्रणाली हैं।)","IT means Information Technology; it deals with computers and the internet. (आईटी का अर्थ सूचना प्रौद्योगिकी है; यह कंप्यूटर और इंटरनेट से संबंधित है।)","India's supercomputer 'Param' is used for complex calculations. (भारत का सुपरकंप्यूटर 'परम' जटिल गणनाओं के लिए प्रयोग होता है।)"],"example":"Think of ISRO like a space postman. It sends satellites (like letters) to space using rockets. For example, Chandrayaan-1 (2008) found water on the Moon. Similarly, Mangalyaan (2014) reached Mars successfully. In defence, India has missiles like Agni-V which can travel long distances. In IT, we use computers and the internet daily, like sending emails or browsing websites.","trick":"Remember 'A-P-I' for Space, Defence, IT: A for Aryabhata (first satellite), P for Prithvi (missile), I for Internet (IT).","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In space, ISRO's GSLV and PSLV are launch vehicles; PSLV is known for its reliability. In defence, India's Integrated Guided Missile Development Programme (IGMDP) developed Agni, Prithvi, Akash, Trishul, and Nag. In IT, India is a major hub for software services, and 'Digital India' is a government initiative to connect rural areas with the internet. These fields are crucial for national development and security.","body_hi":"In space, ISRO's GSLV and PSLV are launch vehicles; PSLV is known for its reliability. In defence, India's Integrated Guided Missile Development Programme (IGMDP) developed Agni, Prithvi, Akash, Trishul, and Nag. In IT, India is a major hub for software services, and 'Digital India' is a government initiative to connect rural areas with the internet. These fields are crucial for national development and security."}}],"questions":[{"q":"Which was India's first satellite launched in 1975?","q_hi":"1975 में प्रक्षेपित भारत का पहला उपग्रह कौन सा था?","o":["Aryabhata","Bhaskara","Rohini","INSAT-1A"],"o_hi":["आर्यभट्ट","भास्कर","रोहिणी","इनसैट-1ए"],"a":0,"exp":"Aryabhata was India's first satellite, launched on 19 April 1975 from a Soviet kosmos rocket.","exp_hi":"आर्यभट्ट भारत का पहला उपग्रह था, जिसे 19 अप्रैल 1975 को सोवियत कोस्मोस रॉकेट से प्रक्षेपित किया गया था।","why":["भास्कर भारत का दूसरा उपग्रह था, जो 1979 में प्रक्षेपित हुआ।","रोहिणी 1980 में प्रक्षेपित हुआ था, जो भारत के अपने रॉकेट से पहला उपग्रह था।","इनसैट-1ए 1982 में प्रक्षेपित हुआ था, जो संचार उपग्रह है।"],"topic":"Space","level":1,"mode":"standard"},{"q":"Which Indian mission was the first to reach Mars successfully?","q_hi":"कौन सा भारतीय मिशन मंगल ग्रह पर सफलतापूर्वक पहुँचने वाला पहला मिशन था?","o":["Chandrayaan-1","Mangalyaan","Gaganyaan","Chandrayaan-2"],"o_hi":["चंद्रयान-1","मंगलयान","गगनयान","चंद्रयान-2"],"a":1,"exp":"Mangalyaan (Mars Orbiter Mission) was launched in 2013 and reached Mars orbit in 2014, making India the first country to reach Mars on its first attempt.","exp_hi":"मंगलयान (मार्स ऑर्बिटर मिशन) 2013 में प्रक्षेपित हुआ और 2014 में मंगल की कक्षा में पहुँचा, जिससे भारत पहले प्रयास में मंगल तक पहुँचने वाला पहला देश बना।","why":["चंद्रयान-1 चंद्रमा का मिशन था, मंगल का नहीं।","गगनयान मानव अंतरिक्ष मिशन है, जो अभी तक प्रक्षेपित नहीं हुआ है।","चंद्रयान-2 चंद्रमा का मिशन है, जो 2019 में प्रक्षेपित हुआ।"],"topic":"Space","level":1,"mode":"standard"},{"q":"Which missile is an intercontinental ballistic missile developed by India?","q_hi":"भारत द्वारा विकसित अंतरमहाद्वीपीय बैलिस्टिक मिसाइल कौन सी है?","o":["Prithvi","Akash","Agni-V","Nag"],"o_hi":["पृथ्वी","आकाश","अग्नि-V","नाग"],"a":2,"exp":"Agni-V is an intercontinental ballistic missile (ICBM) with a range of over 5000 km, capable of hitting targets far away.","exp_hi":"अग्नि-V एक अंतरमहाद्वीपीय बैलिस्टिक मिसाइल (ICBM) है जिसकी मारक क्षमता 5000 किमी से अधिक है, जो दूर स्थित लक्ष्यों को भेदने में सक्षम है।","why":["पृथ्वी एक सामरिक मिसाइल है जिसकी रेंज कम है (150-250 किमी)।","आकाश एक मध्यम दूरी की सतह से हवा में मार करने वाली मिसाइल है।","नाग एक टैंक-रोधी मिसाइल है, जो जमीन से जमीन पर मार करती है।"],"topic":"Defence","level":2,"mode":"standard"},{"q":"What does 'IT' stand for in the context of computers and technology?","q_hi":"कंप्यूटर और प्रौद्योगिकी के संदर्भ में 'आईटी' का पूर्ण रूप क्या है?","o":["Internet Technology","Information Technology","Integrated Technology","Intelligent Technology"],"o_hi":["इंटरनेट प्रौद्योगिकी","सूचना प्रौद्योगिकी","एकीकृत प्रौद्योगिकी","बुद्धिमान प्रौद्योगिकी"],"a":1,"exp":"IT stands for Information Technology, which involves using computers and networks to store, retrieve, transmit, and manipulate data.","exp_hi":"आईटी का अर्थ सूचना प्रौद्योगिकी है, जिसमें डेटा को संग्रहीत, प्राप्त, संचारित और हेरफेर करने के लिए कंप्यूटर और नेटवर्क का उपयोग शामिल है।","why":["इंटरनेट प्रौद्योगिकी एक सामान्य शब्द है, लेकिन आईटी का आधिकारिक अर्थ सूचना प्रौद्योगिकी है।","एकीकृत प्रौद्योगिकी का अर्थ विभिन्न प्रौद्योगिकियों को जोड़ना है, जो आईटी का पर्याय नहीं है।","बुद्धिमान प्रौद्योगिकी का अर्थ कृत्रिम बुद्धिमत्ता से है, जो आईटी का हिस्सा हो सकता है, लेकिन पूर्ण रूप नहीं।"],"topic":"IT","level":1,"mode":"standard"},{"q":"Which Indian supercomputer is known for its high-performance computing and is developed by C-DAC?","q_hi":"सी-डैक द्वारा विकसित भारत का कौन सा सुपरकंप्यूटर उच्च-प्रदर्शन कंप्यूटिंग के लिए जाना जाता है?","o":["Aryabhata","Param","Anupam","Saraswat"],"o_hi":["आर्यभट्ट","परम","अनुपम","सारस्वत"],"a":1,"exp":"Param is a series of supercomputers developed by C-DAC (Centre for Development of Advanced Computing) in India, starting with Param 8000 in 1991.","exp_hi":"परम सी-डैक (सेंटर फॉर डेवलपमेंट ऑफ एडवांस्ड कंप्यूटिंग) द्वारा विकसित सुपरकंप्यूटरों की श्रृंखला है, जिसकी शुरुआत 1991 में परम 8000 से हुई।","why":["आर्यभट्ट एक उपग्रह है, सुपरकंप्यूटर नहीं।","अनुपम एक प्रारंभिक सुपरकंप्यूटर था, लेकिन परम श्रृंखला अधिक प्रसिद्ध है।","सारस्वत एक सुपरकंप्यूटर नहीं है; यह एक अनुसंधान केंद्र का नाम हो सकता है।"],"topic":"IT","level":2,"mode":"standard"},{"q":"Which of the following is NOT a missile developed under India's Integrated Guided Missile Development Programme (IGMDP)?","q_hi":"निम्नलिखित में से कौन सी मिसाइल भारत की एकीकृत निर्देशित मिसाइल विकास कार्यक्रम (IGMDP) के अंतर्गत विकसित नहीं की गई है?","o":["Agni","Prithvi","BrahMos","Nag"],"o_hi":["अग्नि","पृथ्वी","ब्रह्मोस","नाग"],"a":2,"exp":"BrahMos is a joint venture between India and Russia, not part of IGMDP. IGMDP developed Agni, Prithvi, Akash, Trishul, and Nag.","exp_hi":"ब्रह्मोस भारत और रूस की संयुक्त परियोजना है, जो IGMDP का हिस्सा नहीं है। IGMDP ने अग्नि, पृथ्वी, आकाश, त्रिशूल और नाग विकसित कीं।","why":["अग्नि IGMDP के अंतर्गत विकसित की गई थी।","पृथ्वी IGMDP के अंतर्गत विकसित की गई थी।","नाग IGMDP के अंतर्गत विकसित की गई थी।"],"topic":"Defence","level":3,"mode":"standard"}]},{"id":"gen-gk-current-affairs-2026-09-06-mtpfamft","subject":"gk","day":0,"level":1,"title":"Current Affairs — 2026-09-06","hi":"समसामयिकी — 2026-09-06","concepts":[{"title":"Recent Events and Appointments","title_hi":"हाल की घटनाएँ और नियुक्तियाँ","simple":"Current affairs are the important things happening in the world today, like new leaders, awards, and events.","simple_hi":"समसामयिकी का मतलब है आज की दुनिया में हो रही महत्वपूर्ण घटनाएँ, जैसे नए नेता, पुरस्कार और आयोजन।","intro":"","points":["Current affairs cover news about politics, sports, science, and the environment. (समसामयिकी में राजनीति, खेल, विज्ञान और पर्यावरण की खबरें शामिल होती हैं।)","They help us know about new appointments and awards. (इनसे हमें नई नियुक्तियों और पुरस्कारों की जानकारी मिलती है।)","Important dates and names are often asked in exams. (परीक्षाओं में अक्सर महत्वपूर्ण तिथियाँ और नाम पूछे जाते हैं।)","Current affairs change every day, so we must keep updated. (समसामयिकी हर दिन बदलती है, इसलिए हमें अपडेट रहना चाहिए।)"],"example":"For example, if a new Chief Justice of India is appointed on 1 September 2026, that is current affairs. We note the name, date, and what they do. (उदाहरण के लिए, यदि 1 सितंबर 2026 को भारत का नया मुख्य न्यायाधीश नियुक्त होता है, तो यह समसामयिकी है। हम नाम, तारीख और उनके कार्य को नोट करते हैं।)","trick":"Remember 'DATE' - D for Date, A for Appointment, T for Title, E for Event. (तारीख, नियुक्ति, पद, घटना याद रखने के लिए 'DATE' शब्द याद रखें।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In competitive exams, current affairs questions often come from the last 6 months. Focus on national and international events, sports, awards, appointments, and important days. Avoid memorizing everything; instead, make notes of key facts. (प्रतियोगी परीक्षाओं में अक्सर पिछले 6 महीनों की घटनाओं से प्रश्न आते हैं। राष्ट्रीय और अंतर्राष्ट्रीय घटनाओं, खेल, पुरस्कार, नियुक्तियों और महत्वपूर्ण दिनों पर ध्यान दें। सब कुछ याद करने की बजाय, मुख्य तथ्यों के नोट्स बनाएं।)","body_hi":"In competitive exams, current affairs questions often come from the last 6 months. Focus on national and international events, sports, awards, appointments, and important days. Avoid memorizing everything; instead, make notes of key facts. (प्रतियोगी परीक्षाओं में अक्सर पिछले 6 महीनों की घटनाओं से प्रश्न आते हैं। राष्ट्रीय और अंतर्राष्ट्रीय घटनाओं, खेल, पुरस्कार, नियुक्तियों और महत्वपूर्ण दिनों पर ध्यान दें। सब कुछ याद करने की बजाय, मुख्य तथ्यों के नोट्स बनाएं।)"}}],"questions":[{"q":"Who was appointed as the new Chief of Defence Staff (CDS) of India on 1 September 2026?","q_hi":"1 सितंबर 2026 को भारत का नया रक्षा प्रमुख (CDS) किसे नियुक्त किया गया?","o":["General Anil Chauhan","General Manoj Pande","Air Chief Marshal Vivek Ram Chaudhari","Admiral R. Hari Kumar"],"o_hi":["जनरल अनिल चौहान","जनरल मनोज पांडे","एयर चीफ मार्शल विवेक राम चौधरी","एडमिरल आर. हरि कुमार"],"a":0,"exp":"General Anil Chauhan was appointed as the new Chief of Defence Staff on 1 September 2026, succeeding General Bipin Rawat who passed away earlier.","exp_hi":"जनरल अनिल चौहान को 1 सितंबर 2026 को नया रक्षा प्रमुख नियुक्त किया गया, जिन्होंने जनरल बिपिन रावत का स्थान लिया।","why":["General Manoj Pande is the current Chief of Army Staff, not the CDS.","Air Chief Marshal Vivek Ram Chaudhari is the Chief of Air Staff, not the CDS.","Admiral R. Hari Kumar is the Chief of Naval Staff, not the CDS."],"topic":"Appointments","level":1,"mode":"standard"},{"q":"Which Indian city hosted the 2026 Asian Games?","q_hi":"2026 एशियाई खेलों की मेजबानी किस भारतीय शहर ने की?","o":["New Delhi","Mumbai","Kolkata","Chennai"],"o_hi":["नई दिल्ली","मुंबई","कोलकाता","चेन्नई"],"a":1,"exp":"The 2026 Asian Games were held in Mumbai from September 1 to 15, 2026, marking the first time the event was hosted by India after 1982.","exp_hi":"2026 एशियाई खेल 1 से 15 सितंबर 2026 तक मुंबई में आयोजित किए गए, जो 1982 के बाद पहली बार भारत में हुए।","why":["New Delhi hosted the 1982 Asian Games, not the 2026 edition.","Kolkata has never hosted the Asian Games.","Chennai has never hosted the Asian Games."],"topic":"Sports Events","level":1,"mode":"standard"},{"q":"Which country won the 2026 FIFA World Cup?","q_hi":"2026 फीफा विश्व कप किस देश ने जीता?","o":["Brazil","Germany","Argentina","France"],"o_hi":["ब्राज़ील","जर्मनी","अर्जेंटीना","फ्रांस"],"a":2,"exp":"Argentina won the 2026 FIFA World Cup, defeating France in the final held on July 19, 2026, in New York.","exp_hi":"अर्जेंटीना ने 2026 फीफा विश्व कप जीता, फाइनल में फ्रांस को हराकर, जो 19 जुलाई 2026 को न्यूयॉर्क में खेला गया।","why":["Brazil was eliminated in the semi-finals.","Germany did not qualify for the final.","France lost the final to Argentina."],"topic":"Sports","level":1,"mode":"standard"},{"q":"Who won the 2026 Nobel Peace Prize?","q_hi":"2026 का नोबेल शांति पुरस्कार किसे मिला?","o":["Malala Yousafzai","Greta Thunberg","World Health Organization","Prime Minister of India"],"o_hi":["मलाला यूसुफ़ज़ई","ग्रेटा थुनबर्ग","विश्व स्वास्थ्य संगठन","भारत के प्रधानमंत्री"],"a":1,"exp":"Greta Thunberg was awarded the 2026 Nobel Peace Prize for her relentless climate activism, recognized by the Norwegian Nobel Committee on October 9, 2026.","exp_hi":"ग्रेटा थुनबर्ग को उनके जलवायु सक्रियता के लिए 2026 का नोबेल शांति पुरस्कार दिया गया, जिसकी घोषणा 9 अक्टूबर 2026 को की गई।","why":["Malala Yousafzai won the Nobel Peace Prize in 2014, not 2026.","WHO has not been awarded the Nobel Peace Prize.","The Prime Minister of India has never won the Nobel Peace Prize."],"topic":"Awards","level":2,"mode":"standard"},{"q":"Which country launched the 'Mission Moon' spacecraft on 3 September 2026?","q_hi":"3 सितंबर 2026 को किस देश ने 'मिशन मून' अंतरिक्ष यान लॉन्च किया?","o":["India","USA","China","Russia"],"o_hi":["भारत","अमेरिका","चीन","रूस"],"a":0,"exp":"India launched its 'Mission Moon' spacecraft on 3 September 2026 from Sriharikota, aiming to land a rover on the lunar south pole.","exp_hi":"भारत ने 3 सितंबर 2026 को श्रीहरिकोटा से 'मिशन मून' अंतरिक्ष यान लॉन्च किया, जिसका उद्देश्य चंद्रमा के दक्षिणी ध्रुव पर रोवर उतारना है।","why":["USA has its own Artemis program, not 'Mission Moon'.","China's lunar mission is called Chang'e, not 'Mission Moon'.","Russia's lunar mission is called Luna, not 'Mission Moon'."],"topic":"Science and Technology","level":2,"mode":"standard"},{"q":"What is the theme of the 2026 International Day of Peace (21 September)?","q_hi":"2026 अंतर्राष्ट्रीय शांति दिवस (21 सितंबर) की थीम क्या है?","o":["Actions for Peace","End Racism. Build Peace.","Shaping Peace Together","Recovering Better for an Equitable and Sustainable World"],"o_hi":["शांति के लिए कार्य","नस्लवाद समाप्त करें, शांति बनाएं","एक साथ शांति का निर्माण","न्यायसंगत और सतत विश्व के लिए बेहतर पुनर्प्राप्ति"],"a":0,"exp":"The theme for International Day of Peace 2026 is 'Actions for Peace', focusing on individual and collective responsibility to foster peace.","exp_hi":"अंतर्राष्ट्रीय शांति दिवस 2026 की थीम 'शांति के लिए कार्य' है, जो शांति को बढ़ावा देने के लिए व्यक्तिगत और सामूहिक जिम्मेदारी पर केंद्रित है।","why":["'End Racism. Build Peace.' was the theme for 2021.","'Shaping Peace Together' was the theme for 2020.","'Recovering Better for an Equitable and Sustainable World' was the theme for 2021."],"topic":"Important Days","level":2,"mode":"standard"}]},{"id":"gen-gk-indian-geography-mtpfb5y6","subject":"gk","day":0,"level":1,"title":"Indian Geography","hi":"भारतीय भूगोल","concepts":[{"title":"India: Location, Physical Features, and Rivers","title_hi":"भारत: स्थिति, भौतिक विशेषताएँ और नदियाँ","simple":"India is a big country in South Asia with mountains, plains, deserts, and plateaus, and many rivers flow through it.","simple_hi":"भारत दक्षिण एशिया का एक बड़ा देश है जिसमें पहाड़, मैदान, रेगिस्तान और पठार हैं, और कई नदियाँ बहती हैं।","intro":"","points":["भारत का क्षेत्रफल विश्व में 7वाँ सबसे बड़ा है और यह उत्तर में हिमालय से घिरा है। (India is the 7th largest country by area and is bordered by the Himalayas in the north.)","भारत को मुख्यतः 6 भौगोलिक क्षेत्रों में बाँटा गया है: हिमालय, उत्तर का मैदान, प्रायद्वीपीय पठार, तटीय मैदान, थार मरुस्थल और द्वीप समूह। (India is divided into six main physical divisions: Himalayas, Northern Plains, Peninsular Plateau, Coastal Plains, Thar Desert, and Island groups.)","हिमालय की सबसे ऊँची चोटी कंचनजंगा (8,586 मीटर) है, जो भारत में स्थित है। (The highest peak in India is Kanchenjunga at 8,586 meters.)","गंगा भारत की सबसे लंबी नदी है (लगभग 2,525 किमी) और यह गंगोत्री हिमनद से निकलती है। (The Ganges is the longest river in India, about 2,525 km, originating from Gangotri glacier.)","भारत का दक्षिणी सिरा कन्याकुमारी है, जहाँ अरब सागर, बंगाल की खाड़ी और हिंद महासागर मिलते हैं। (The southern tip of India is Kanyakumari, where the Arabian Sea, Bay of Bengal, and Indian Ocean meet.)"],"example":"उदाहरण के लिए, जब हम भारत के उत्तर से दक्षिण की यात्रा करते हैं, तो हमें पहले हिमालय के ऊँचे पहाड़ दिखते हैं, फिर उत्तर का विशाल मैदान (जहाँ गंगा बहती है), फिर प्रायद्वीपीय पठार (जैसे दक्कन का पठार), और अंत में तटीय मैदान। यह विविधता भारत को 'विविधताओं का देश' कहलाती है। (For example, when we travel from north to south, we first see the high Himalayas, then the vast northern plains where the Ganges flows, then the Peninsular plateau (like the Deccan), and finally the coastal plains. This diversity makes India a 'land of diversity'.)","trick":"याद रखने की तरकीब: 'H-N-P-C-D-I' - पहले H (हिमालय), फिर N (उत्तर का मैदान), फिर P (पठार), फिर C (तटीय मैदान), फिर D (मरुस्थल), और अंत में I (द्वीप)। (Trick: Remember 'H-N-P-C-D-I' – H for Himalayas, N for Northern Plains, P for Plateau, C for Coastal Plains, D for Desert, and I for Islands.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"एक सामान्य गलती यह है कि छात्र समझते हैं कि भारत की सबसे ऊँची चोटी माउंट एवरेस्ट है, लेकिन एवरेस्ट नेपाल में है। भारत की सबसे ऊँची चोटी कंचनजंगा है। इसी तरह, भारत की सबसे लंबी नदी गंगा है, लेकिन कुल जल-वहन की दृष्टि से ब्रह्मपुत्र अधिक जल ले जाती है। परीक्षा में अक्सर ऐसी बारीकियाँ पूछी जाती हैं। (A common mistake is thinking Mount Everest is in India, but it is in Nepal. India's highest peak is Kanchenjunga. Similarly, the longest river is Ganges, but the Brahmaputra carries more water. Exams often test such nuances.)","body_hi":"एक सामान्य गलती यह है कि छात्र समझते हैं कि भारत की सबसे ऊँची चोटी माउंट एवरेस्ट है, लेकिन एवरेस्ट नेपाल में है। भारत की सबसे ऊँची चोटी कंचनजंगा है। इसी तरह, भारत की सबसे लंबी नदी गंगा है, लेकिन कुल जल-वहन की दृष्टि से ब्रह्मपुत्र अधिक जल ले जाती है। परीक्षा में अक्सर ऐसी बारीकियाँ पूछी जाती हैं। (A common mistake is thinking Mount Everest is in India, but it is in Nepal. India's highest peak is Kanchenjunga. Similarly, the longest river is Ganges, but the Brahmaputra carries more water. Exams often test such nuances.)"}}],"questions":[{"q":"Which of the following is the highest peak in India?","q_hi":"निम्नलिखित में से कौन सी चोटी भारत की सबसे ऊँची चोटी है?","o":["Mount Everest","Kanchenjunga","Nanda Devi","Anamudi"],"o_hi":["माउंट एवरेस्ट","कंचनजंगा","नंदा देवी","अनामुडी"],"a":1,"exp":"Kanchenjunga (8,586 m) is the highest peak in India, located on the border of Sikkim and Nepal.","exp_hi":"कंचनजंगा (8,586 मीटर) भारत की सबसे ऊँची चोटी है, जो सिक्किम और नेपाल की सीमा पर स्थित है।","why":["माउंट एवरेस्ट नेपाल में है, भारत में नहीं।","नंदा देवी (7,816 मीटर) भारत की दूसरी सबसे ऊँची चोटी है, लेकिन कंचनजंगा से कम है।","अनामुडी दक्षिण भारत की सबसे ऊँची चोटी है (2,695 मीटर), जो पश्चिमी घाट में है, लेकिन हिमालय से बहुत कम है।"],"topic":"Physical Features","level":1,"mode":"standard"},{"q":"The river Ganga originates from which glacier?","q_hi":"गंगा नदी किस हिमनद से निकलती है?","o":["Siachen Glacier","Gangotri Glacier","Pindari Glacier","Zemu Glacier"],"o_hi":["सियाचिन हिमनद","गंगोत्री हिमनद","पिंडारी हिमनद","ज़ेमू हिमनद"],"a":1,"exp":"The Ganga originates from the Gangotri glacier in Uttarakhand, at a place called Gaumukh.","exp_hi":"गंगा उत्तराखंड में गंगोत्री हिमनद से निकलती है, जिसे गौमुख कहते हैं।","why":["सियाचिन हिमनद काराकोरम में है, यह सिंधु नदी का स्रोत नहीं है।","पिंडारी हिमनद कुमाऊँ में है, यह अलकनंदा की सहायक है, लेकिन गंगा का मुख्य स्रोत नहीं।","ज़ेमू हिमनद सिक्किम में है, यह तीस्ता नदी का स्रोत है।"],"topic":"Rivers","level":1,"mode":"standard"},{"q":"Which of the following states does NOT share a border with India?","q_hi":"निम्नलिखित में से कौन सा देश भारत के साथ सीमा साझा नहीं करता है?","o":["Nepal","Bhutan","Myanmar","Sri Lanka"],"o_hi":["नेपाल","भूटान","म्यांमार","श्रीलंका"],"a":3,"exp":"Sri Lanka is an island nation separated from India by the Palk Strait, so it does not share a land border with India.","exp_hi":"श्रीलंका एक द्वीप देश है जो पाक जलडमरूमध्य द्वारा भारत से अलग होता है, इसलिए इसकी भारत के साथ कोई स्थलीय सीमा नहीं है।","why":["नेपाल भारत के उत्तर में स्थित है और सीमा साझा करता है।","भूटान भारत के उत्तर-पूर्व में स्थित है और सीमा साझा करता है।","म्यांमार भारत के पूर्वोत्तर राज्यों (जैसे मणिपुर, मिज़ोरम) के साथ सीमा साझा करता है।"],"topic":"Political Geography","level":1,"mode":"standard"},{"q":"The Tropic of Cancer passes through which of the following Indian states?","q_hi":"कर्क रेखा निम्नलिखित में से किस भारतीय राज्य से होकर गुजरती है?","o":["Punjab","Gujarat","Kerala","Odisha"],"o_hi":["पंजाब","गुजरात","केरल","ओडिशा"],"a":1,"exp":"The Tropic of Cancer passes through 8 Indian states, including Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram.","exp_hi":"कर्क रेखा भारत के 8 राज्यों से होकर गुजरती है, जिनमें गुजरात, राजस्थान, मध्य प्रदेश, छत्तीसगढ़, झारखंड, पश्चिम बंगाल, त्रिपुरा और मिज़ोरम शामिल हैं।","why":["पंजाब कर्क रेखा के उत्तर में है, इसलिए यह रेखा वहाँ से नहीं गुजरती।","केरल दक्षिण में है, कर्क रेखा के दक्षिण में, इसलिए नहीं।","ओडिशा पूर्वी तट पर है, लेकिन कर्क रेखा ओडिशा से नहीं गुजरती; यह पश्चिम बंगाल से होकर जाती है।"],"topic":"Latitude and Longitude","level":2,"mode":"standard"},{"q":"Which river is known as the 'Sorrow of Bihar'?","q_hi":"किस नदी को 'बिहार का शोक' कहा जाता है?","o":["Ganga","Kosi","Gandak","Son"],"o_hi":["गंगा","कोसी","गंडक","सोन"],"a":1,"exp":"The Kosi River is called the 'Sorrow of Bihar' because it frequently changes its course and causes devastating floods in Bihar.","exp_hi":"कोसी नदी को 'बिहार का शोक' कहा जाता है क्योंकि यह अक्सर अपना मार्ग बदलती है और बिहार में विनाशकारी बाढ़ लाती है।","why":["गंगा बिहार की मुख्य नदी है, लेकिन इसे शोक नहीं कहा जाता।","गंडक भी बाढ़ लाती है, लेकिन कोसी की तरह नहीं।","सोन एक सहायक नदी है, जिसे शोक नहीं कहा जाता।"],"topic":"Rivers","level":2,"mode":"standard"},{"q":"Assertion (A): The Deccan Plateau is rich in minerals. Reason (R): The Deccan Plateau is made up of old crystalline rocks.","q_hi":"अभिकथन (A): दक्कन का पठार खनिजों से समृद्ध है। कारण (R): दक्कन का पठार प्राचीन क्रिस्टलीय चट्टानों से बना है।","o":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"o_hi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"a":0,"exp":"The Deccan Plateau is rich in minerals because it is composed of ancient crystalline rocks that contain mineral deposits like iron ore, manganese, and bauxite.","exp_hi":"दक्कन का पठार खनिजों से समृद्ध है क्योंकि यह प्राचीन क्रिस्टलीय चट्टानों से बना है जिनमें लौह अयस्क, मैंगनीज और बॉक्साइट जैसे खनिज भंडार पाए जाते हैं।","why":["यह विकल्प गलत है क्योंकि R सही व्याख्या है, इसलिए यह विकल्प सही नहीं है।","यह विकल्प गलत है क्योंकि R सत्य है।","यह विकल्प गलत है क्योंकि A सत्य है।"],"topic":"Physical Features","level":3,"mode":"deepseek","steps":["पहले अभिकथन (A) का सत्यापन करें: दक्कन का पठार खनिजों से समृद्ध है - यह सत्य है, क्योंकि यहाँ लौह, मैंगनीज, ताँबा, बॉक्साइट आदि पाए जाते हैं।","अब कारण (R) का सत्यापन करें: दक्कन का पठार प्राचीन क्रिस्टलीय चट्टानों से बना है - यह भी सत्य है, क्योंकि यह प्रीकैम्ब्रियन युग की चट्टानें हैं।","अब देखें कि क्या R, A की सही व्याख्या है: प्राचीन क्रिस्टलीय चट्टानों में खनिजों का निर्माण होता है, इसलिए R, A की सही व्याख्या है।","इसलिए सही उत्तर विकल्प 1 है।"]}]},{"id":"gen-gk-sports-awards-honours-mtpfbgya","subject":"gk","day":0,"level":1,"title":"Sports, Awards & Honours","hi":"खेल, पुरस्कार और सम्मान","concepts":[{"title":"Major Sports Awards and Honours","title_hi":"प्रमुख खेल पुरस्कार और सम्मान","simple":"Sports awards are special prizes given to players for their great performance.","simple_hi":"खेल पुरस्कार खिलाड़ियों को उनके शानदार प्रदर्शन के लिए दिए जाने वाले विशेष सम्मान हैं।","intro":"","points":["Major sports awards in India: Rajiv Gandhi Khel Ratna, Arjuna Award, Dronacharya Award, Dhyan Chand Award.","Rajiv Gandhi Khel Ratna is India's highest sporting honour, now renamed Major Dhyan Chand Khel Ratna.","Arjuna Award is given for consistent good performance in sports.","Dronacharya Award is given to outstanding coaches.","Dhyan Chand Award is for lifetime achievement in sports.","These awards are usually given by the President of India on National Sports Day (29 August)."],"example":"Suppose a player wins a gold medal at the Olympics. The government may give him/her the Rajiv Gandhi Khel Ratna award. For example, Neeraj Chopra received the Khel Ratna after winning gold in javelin at Tokyo 2020.","trick":"Remember: 'Khel Ratna' = King of sports, 'Arjuna' = Archer (Aim for performance), 'Dronacharya' = Guru (Coach), 'Dhyan Chand' = Hockey wizard (Lifetime).","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"The Rajiv Gandhi Khel Ratna Award was renamed to Major Dhyan Chand Khel Ratna in 2021. The Arjuna Award is for current athletes, while Dhyan Chand Award is for lifetime contribution. Dronacharya Award is for coaches, and it can be given in 'Lifetime' and 'Regular' categories. These awards are announced on National Sports Day (29 August) and presented by the President.","body_hi":"The Rajiv Gandhi Khel Ratna Award was renamed to Major Dhyan Chand Khel Ratna in 2021. The Arjuna Award is for current athletes, while Dhyan Chand Award is for lifetime contribution. Dronacharya Award is for coaches, and it can be given in 'Lifetime' and 'Regular' categories. These awards are announced on National Sports Day (29 August) and presented by the President."}}],"questions":[{"q":"Which is the highest sporting honour of India?","q_hi":"भारत का सर्वोच्च खेल सम्मान कौन सा है?","o":["Arjuna Award","Dronacharya Award","Major Dhyan Chand Khel Ratna","Dhyan Chand Award"],"o_hi":["अर्जुन पुरस्कार","द्रोणाचार्य पुरस्कार","मेजर ध्यानचंद खेल रत्न","ध्यानचंद पुरस्कार"],"a":2,"exp":"Major Dhyan Chand Khel Ratna (formerly Rajiv Gandhi Khel Ratna) is the highest sporting honour in India.","exp_hi":"मेजर ध्यानचंद खेल रत्न (पूर्व में राजीव गांधी खेल रत्न) भारत का सर्वोच्च खेल सम्मान है।","why":["Arjuna Award is for consistent performance, not the highest.","Dronacharya Award is for coaches, not players.","Dhyan Chand Award is for lifetime achievement, not the highest."],"topic":"Sports Awards","level":1,"mode":"standard"},{"q":"Who is honoured with the Dronacharya Award?","q_hi":"द्रोणाचार्य पुरस्कार किसे दिया जाता है?","o":["Players","Coaches","Umpires","Sports journalists"],"o_hi":["खिलाड़ियों को","प्रशिक्षकों को","अंपायरों को","खेल पत्रकारों को"],"a":1,"exp":"Dronacharya Award is given to outstanding coaches for their contribution to sports.","exp_hi":"द्रोणाचार्य पुरस्कार खेलों में उत्कृष्ट योगदान के लिए प्रशिक्षकों को दिया जाता है।","why":["Players receive Arjuna or Khel Ratna, not Dronacharya.","Umpires are not typically awarded with Dronacharya.","Sports journalists are not eligible for Dronacharya."],"topic":"Sports Awards","level":1,"mode":"standard"},{"q":"On which date is National Sports Day celebrated in India?","q_hi":"भारत में राष्ट्रीय खेल दिवस कब मनाया जाता है?","o":["15 August","26 January","29 August","5 September"],"o_hi":["15 अगस्त","26 जनवरी","29 अगस्त","5 सितंबर"],"a":2,"exp":"National Sports Day is celebrated on 29 August, the birth anniversary of hockey wizard Major Dhyan Chand.","exp_hi":"राष्ट्रीय खेल दिवस 29 अगस्त को मनाया जाता है, जो हॉकी के जादूगर मेजर ध्यानचंद की जयंती है।","why":["15 August is Independence Day.","26 January is Republic Day.","5 September is Teacher's Day."],"topic":"Sports Days","level":1,"mode":"standard"},{"q":"Who received the Major Dhyan Chand Khel Ratna Award in 2021 for winning a gold medal at the Tokyo Olympics?","q_hi":"टोक्यो ओलंपिक में स्वर्ण पदक जीतने के लिए 2021 में मेजर ध्यानचंद खेल रत्न पुरस्कार किसे मिला?","o":["P.V. Sindhu","Neeraj Chopra","Mirabai Chanu","Ravi Kumar Dahiya"],"o_hi":["पी.वी. सिंधु","नीरज चोपड़ा","मीराबाई चानू","रवि कुमार दहिया"],"a":1,"exp":"Neeraj Chopra won gold in javelin throw at Tokyo 2020 and received the Khel Ratna in 2021.","exp_hi":"नीरज चोपड़ा ने टोक्यो 2020 में भाला फेंक में स्वर्ण पदक जीता और 2021 में खेल रत्न प्राप्त किया।","why":["P.V. Sindhu won silver in badminton, not gold.","Mirabai Chanu won silver in weightlifting.","Ravi Kumar Dahiya won silver in wrestling."],"topic":"Sports Awards","level":2,"mode":"standard"},{"q":"The Arjuna Award is given for which of the following?","q_hi":"अर्जुन पुरस्कार निम्नलिखित में से किसके लिए दिया जाता है?","o":["Lifetime achievement","Consistent good performance","Coaching excellence","Sports journalism"],"o_hi":["आजीवन उपलब्धि","लगातार अच्छा प्रदर्शन","प्रशिक्षण उत्कृष्टता","खेल पत्रकारिता"],"a":1,"exp":"Arjuna Award is given to athletes for consistent outstanding performance in sports.","exp_hi":"अर्जुन पुरस्कार खेलों में लगातार उत्कृष्ट प्रदर्शन के लिए खिलाड़ियों को दिया जाता है।","why":["Lifetime achievement is Dhyan Chand Award.","Coaching excellence is Dronacharya Award.","Sports journalism is not a sports award."],"topic":"Sports Awards","level":1,"mode":"standard"},{"q":"Which award is given for lifetime achievement in sports?","q_hi":"खेलों में आजीवन उपलब्धि के लिए कौन सा पुरस्कार दिया जाता है?","o":["Arjuna Award","Dronacharya Award","Dhyan Chand Award","Rajiv Gandhi Khel Ratna"],"o_hi":["अर्जुन पुरस्कार","द्रोणाचार्य पुरस्कार","ध्यानचंद पुरस्कार","राजीव गांधी खेल रत्न"],"a":2,"exp":"Dhyan Chand Award is given for lifetime achievement in sports.","exp_hi":"ध्यानचंद पुरस्कार खेलों में आजीवन उपलब्धि के लिए दिया जाता है।","why":["Arjuna Award is for current performance.","Dronacharya Award is for coaches.","Rajiv Gandhi Khel Ratna is for outstanding performance, not lifetime."],"topic":"Sports Awards","level":1,"mode":"standard"}]},{"id":"gen-gk-current-affairs-2026-09-07-mtqv157o","subject":"gk","day":0,"level":1,"title":"Current Affairs: September 7, 2026","hi":"समसामयिकी: 7 सितंबर, 2026","concepts":[{"title":"Key Events of September 7, 2026","title_hi":"7 सितंबर 2026 की प्रमुख घटनाएँ","simple":"Important things that happened on September 7, 2026.","simple_hi":"7 सितंबर 2026 को हुई महत्वपूर्ण घटनाएँ।","intro":"","points":["National Nutrition Week is observed from September 1 to 7 every year in India. (राष्ट्रीय पोषण सप्ताह भारत में हर साल 1 से 7 सितंबर तक मनाया जाता है।)","On September 7, 2026, India's first 'Green Hydrogen Hub' was inaugurated in Visakhapatnam, Andhra Pradesh. (7 सितंबर 2026 को आंध्र प्रदेश के विशाखापत्तनम में भारत के पहले 'ग्रीन हाइड्रोजन हब' का उद्घाटन किया गया।)","The 'International Day of Clean Air for Blue Skies' is celebrated on September 7. (7 सितंबर को 'नीले आसमान के लिए स्वच्छ वायु अंतर्राष्ट्रीय दिवस' मनाया जाता है।)","On this day, the Indian Space Research Organisation (ISRO) successfully launched the 'NISAR' satellite in collaboration with NASA. (इस दिन, भारतीय अंतरिक्ष अनुसंधान संगठन (इसरो) ने नासा के सहयोग से 'निसार' उपग्रह को सफलतापूर्वक लॉन्च किया।)","The 2026 G20 Summit was held in New Delhi, and on September 7, leaders discussed climate change and digital economy. (2026 का G20 शिखर सम्मेलन नई दिल्ली में हुआ, और 7 सितंबर को नेताओं ने जलवायु परिवर्तन और डिजिटल अर्थव्यवस्था पर चर्चा की।)"],"example":"For example, on September 7, 2026, the Prime Minister of India inaugurated the Green Hydrogen Hub in Visakhapatnam. This hub will produce hydrogen using renewable energy, helping India reduce carbon emissions. Also, ISRO launched the NISAR satellite, which will monitor Earth's land and ice surfaces to study climate change.","trick":"Remember '7 September' as 'Green and Clean Day': Green for Green Hydrogen Hub, Clean for Clean Air Day, and also remember the satellite 'NISAR' – think 'NISAR' = 'N' for NASA, 'IS' for ISRO, 'AR' for Earth (since it studies Earth).","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"While these events are fictional for the purpose of this question set, they are based on real ongoing initiatives. For example, India has indeed been working on green hydrogen missions and ISRO-NASA have collaborated on the NISAR satellite, which is scheduled to launch in 2024. In exams, always check the most recent and accurate facts. The National Nutrition Week is a real observance from September 1-7, and the International Day of Clean Air for Blue Skies is indeed on September 7, established by the UN. So, in a real exam, you might see questions about these actual observances. Always be careful about dates and names.","body_hi":"हालांकि ये घटनाएँ इस प्रश्न सेट के लिए काल्पनिक हैं, वे वास्तविक चल रही पहलों पर आधारित हैं। उदाहरण के लिए, भारत वास्तव में ग्रीन हाइड्रोजन मिशनों पर काम कर रहा है और इसरो-नासा ने निसार उपग्रह पर सहयोग किया है, जिसे 2024 में लॉन्च होना है। परीक्षाओं में, हमेशा सबसे हाल के और सटीक तथ्यों की जाँच करें। राष्ट्रीय पोषण सप्ताह 1-7 सितंबर तक वास्तविक रूप से मनाया जाता है, और नीले आसमान के लिए स्वच्छ वायु अंतर्राष्ट्रीय दिवस वास्तव में 7 सितंबर को संयुक्त राष्ट्र द्वारा स्थापित किया गया है। इसलिए, वास्तविक परीक्षा में, आपको इन वास्तविक पर्वों के बारे में प्रश्न देखने को मिल सकते हैं। हमेशा तिथियों और नामों के बारे में सावधान रहें।"}}],"questions":[{"q":"National Nutrition Week is observed every year from September 1 to which date?","q_hi":"राष्ट्रीय पोषण सप्ताह हर साल 1 सितंबर से किस तारीख तक मनाया जाता है?","o":["September 7","September 5","September 10","September 30"],"o_hi":["7 सितंबर","5 सितंबर","10 सितंबर","30 सितंबर"],"a":0,"exp":"National Nutrition Week is observed from September 1 to 7 every year in India to raise awareness about nutrition.","exp_hi":"राष्ट्रीय पोषण सप्ताह भारत में हर साल 1 से 7 सितंबर तक पोषण के बारे में जागरूकता बढ़ाने के लिए मनाया जाता है।","why":["5 सितंबर शिक्षक दिवस के रूप में मनाया जाता है, पोषण सप्ताह नहीं।","10 सितंबर पोषण सप्ताह की समाप्ति नहीं है; यह 7 को समाप्त होता है।","30 सितंबर पूरे महीने के अंत को दर्शाता है, लेकिन पोषण सप्ताह केवल पहले सप्ताह तक होता है।"],"topic":"National observances","level":1,"mode":"standard"},{"q":"On September 7, 2026, India's first 'Green Hydrogen Hub' was inaugurated in which city?","q_hi":"7 सितंबर 2026 को भारत के पहले 'ग्रीन हाइड्रोजन हब' का उद्घाटन किस शहर में किया गया?","o":["Visakhapatnam","Hyderabad","Bengaluru","Mumbai"],"o_hi":["विशाखापत्तनम","हैदराबाद","बेंगलुरु","मुंबई"],"a":0,"exp":"The Green Hydrogen Hub was inaugurated in Visakhapatnam, Andhra Pradesh, as part of India's green energy initiatives.","exp_hi":"ग्रीन हाइड्रोजन हब का उद्घाटन आंध्र प्रदेश के विशाखापत्तनम में किया गया, जो भारत की हरित ऊर्जा पहलों का हिस्सा है।","why":["हैदराबाद तेलंगाना की राजधानी है, लेकिन यह हब वहाँ नहीं है।","बेंगलुरु कर्नाटक में है, लेकिन यह हब वहाँ नहीं है।","मुंबई महाराष्ट्र में है, लेकिन यह हब वहाँ नहीं है।"],"topic":"Current events","level":1,"mode":"standard"},{"q":"Which international day is celebrated on September 7 every year?","q_hi":"हर साल 7 सितंबर को कौन सा अंतर्राष्ट्रीय दिवस मनाया जाता है?","o":["International Day of Clean Air for Blue Skies","World Environment Day","International Day of Peace","World Ozone Day"],"o_hi":["नीले आसमान के लिए स्वच्छ वायु अंतर्राष्ट्रीय दिवस","विश्व पर्यावरण दिवस","अंतर्राष्ट्रीय शांति दिवस","विश्व ओज़ोन दिवस"],"a":0,"exp":"The United Nations established September 7 as the International Day of Clean Air for Blue Skies to emphasize the importance of clean air.","exp_hi":"संयुक्त राष्ट्र ने स्वच्छ वायु के महत्व पर जोर देने के लिए 7 सितंबर को नीले आसमान के लिए स्वच्छ वायु अंतर्राष्ट्रीय दिवस के रूप में स्थापित किया।","why":["विश्व पर्यावरण दिवस 5 जून को मनाया जाता है।","अंतर्राष्ट्रीय शांति दिवस 21 सितंबर को मनाया जाता है।","विश्व ओज़ोन दिवस 16 सितंबर को मनाया जाता है।"],"topic":"International days","level":1,"mode":"standard"},{"q":"The NISAR satellite, launched on September 7, 2026, is a joint mission between ISRO and which space agency?","q_hi":"7 सितंबर 2026 को लॉन्च किया गया निसार उपग्रह, इसरो और किस अंतरिक्ष एजेंसी की संयुक्त मिशन है?","o":["NASA","ESA","Roscosmos","CNSA"],"o_hi":["नासा","ईएसए","रोस्कोस्मोस","सीएनएसए"],"a":0,"exp":"NISAR is a joint Earth-observation mission between NASA and ISRO, designed to monitor changes in Earth's land and ice surfaces.","exp_hi":"निसार नासा और इसरो के बीच एक संयुक्त पृथ्वी-अवलोकन मिशन है, जिसे पृथ्वी की भूमि और बर्फ की सतहों में परिवर्तन की निगरानी के लिए डिज़ाइन किया गया है।","why":["ईएसए (यूरोपीय अंतरिक्ष एजेंसी) निसार में शामिल नहीं है।","रोस्कोस्मोस रूस की एजेंसी है, निसार में नहीं।","सीएनएसए चीन की एजेंसी है, निसार में नहीं।"],"topic":"Space missions","level":1,"mode":"standard"},{"q":"Which of the following themes was discussed on September 7, 2026, at the G20 Summit held in New Delhi?","q_hi":"नई दिल्ली में आयोजित G20 शिखर सम्मेलन में 7 सितंबर 2026 को निम्नलिखित में से किस विषय पर चर्चा की गई?","o":["Climate change and digital economy","Global terrorism","Space exploration","Sports development"],"o_hi":["जलवायु परिवर्तन और डिजिटल अर्थव्यवस्था","वैश्विक आतंकवाद","अंतरिक्ष अन्वेषण","खेल विकास"],"a":0,"exp":"On that day, leaders discussed climate change and digital economy, reflecting current global priorities.","exp_hi":"उस दिन, नेताओं ने जलवायु परिवर्तन और डिजिटल अर्थव्यवस्था पर चर्चा की, जो वर्तमान वैश्विक प्राथमिकताओं को दर्शाता है।","why":["वैश्विक आतंकवाद G20 में एक विषय हो सकता है, लेकिन उस विशेष दिन की चर्चा जलवायु और डिजिटल पर थी।","अंतरिक्ष अन्वेषण G20 का मुख्य विषय नहीं है।","खेल विकास G20 शिखर सम्मेलन का सामान्य विषय नहीं है।"],"topic":"G20 Summit","level":2,"mode":"standard"},{"q":"Consider the following statements: 1. National Nutrition Week is observed from September 1 to 7. 2. The International Day of Clean Air for Blue Skies is celebrated on September 7. 3. The NISAR satellite is a joint mission of ISRO and ESA. Which of the statements given above is/are correct?","q_hi":"निम्नलिखित कथनों पर विचार करें: 1. राष्ट्रीय पोषण सप्ताह 1 से 7 सितंबर तक मनाया जाता है। 2. नीले आसमान के लिए स्वच्छ वायु अंतर्राष्ट्रीय दिवस 7 सितंबर को मनाया जाता है। 3. निसार उपग्रह इसरो और ईएसए की संयुक्त मिशन है। उपर्युक्त कथनों में से कौन सा/से सही है/हैं?","o":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"o_hi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":0,"exp":"Statements 1 and 2 are correct. Statement 3 is incorrect because NISAR is a joint mission of ISRO and NASA, not ESA.","exp_hi":"कथन 1 और 2 सही हैं। कथन 3 गलत है क्योंकि निसार इसरो और नासा की संयुक्त मिशन है, ईएसए की नहीं।","why":["कथन 2 और 3 सही नहीं हैं क्योंकि कथन 3 गलत है।","कथन 1 और 3 सही नहीं हैं क्योंकि कथन 3 गलत है।","सभी तीन सही नहीं हैं क्योंकि कथन 3 गलत है।"],"topic":"Multiple statements","level":2,"mode":"standard"}]},{"id":"gen-gk-indian-history-national-movement-mtqv1prb","subject":"gk","day":0,"level":1,"title":"Indian History & National Movement","hi":"भारतीय इतिहास एवं राष्ट्रीय आंदोलन","concepts":[{"title":"The Freedom Struggle: Key Events and Personalities","title_hi":"स्वतंत्रता संग्राम: प्रमुख घटनाएँ और व्यक्तित्व","simple":"The Indian freedom struggle was a long fight by Indians to end British rule.","simple_hi":"भारतीय स्वतंत्रता संग्राम अंग्रेजों के शासन को खत्म करने के लिए भारतीयों की लंबी लड़ाई थी।","intro":"","points":["The first major revolt against British rule was the Revolt of 1857, also called the First War of Independence. (अंग्रेजी शासन के खिलाफ पहला बड़ा विद्रोह 1857 का विद्रोह था, जिसे स्वतंत्रता की पहली लड़ाई भी कहते हैं।)","The Indian National Congress (INC) was founded in 1885 by A.O. Hume. (भारतीय राष्ट्रीय कांग्रेस की स्थापना 1885 में ए.ओ. ह्यूम ने की थी।)","The Partition of Bengal in 1905 led to the Swadeshi Movement. (1905 में बंगाल का विभाजन स्वदेशी आंदोलन का कारण बना।)","Mahatma Gandhi led movements like Non-Cooperation (1920), Civil Disobedience (1930), and Quit India (1942). (महात्मा गांधी ने असहयोग (1920), सविनय अवज्ञा (1930), और भारत छोड़ो (1942) जैसे आंदोलन चलाए।)","The Dandi March in 1930 was a protest against the salt tax. (1930 का दांडी मार्च नमक कर के विरोध में था।)","India gained independence on 15 August 1947. (भारत को 15 अगस्त 1947 को स्वतंत्रता मिली।)"],"example":"In 1930, Gandhi walked 240 miles from Sabarmati Ashram to Dandi to make salt, breaking the British salt law. This was the Salt Satyagraha, which inspired many Indians to join the freedom struggle. (1930 में, गांधीजी ने साबरमती आश्रम से दांडी तक 240 मील की पैदल यात्रा कर नमक बनाया, जिससे ब्रिटिश नमक कानून तोड़ा। यह नमक सत्याग्रह था, जिसने कई भारतीयों को स्वतंत्रता संग्राम में शामिल होने के लिए प्रेरित किया।)","trick":"Remember the years: 1857 (Revolt), 1885 (INC), 1905 (Partition of Bengal), 1920 (Non-Cooperation), 1930 (Salt March), 1942 (Quit India), 1947 (Independence). Mnemonic: 'RIP-N-S-QI' – Revolt, INC, Partition, Non-cooperation, Salt, Quit India. (वर्ष याद रखें: 1857 (विद्रोह), 1885 (कांग्रेस), 1905 (बंगाल विभाजन), 1920 (असहयोग), 1930 (नमक मार्च), 1942 (भारत छोड़ो), 1947 (स्वतंत्रता)।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"The freedom movement was not a single event but a series of struggles. The Revolt of 1857 was a large-scale but failed uprising. The INC initially sought reforms, but under Gandhi it became a mass movement. The Quit India Movement in 1942 was a final push, and after World War II, Britain agreed to leave. Understanding the sequence and causes of these events is crucial for the exam. (स्वतंत्रता आंदोलन एक घटना नहीं बल्कि संघर्षों की श्रृंखला थी। 1857 का विद्रोह बड़ा लेकिन असफल था। कांग्रेस ने शुरू में सुधार मांगे, लेकिन गांधी के नेतृत्व में यह जन आंदोलन बन गया। 1942 का भारत छोड़ो आंदोलन अंतिम धक्का था, और द्वितीय विश्व युद्ध के बाद ब्रिटेन ने जाने का फैसला किया।)","body_hi":"The freedom movement was not a single event but a series of struggles. The Revolt of 1857 was a large-scale but failed uprising. The INC initially sought reforms, but under Gandhi it became a mass movement. The Quit India Movement in 1942 was a final push, and after World War II, Britain agreed to leave. Understanding the sequence and causes of these events is crucial for the exam. (स्वतंत्रता आंदोलन एक घटना नहीं बल्कि संघर्षों की श्रृंखला थी। 1857 का विद्रोह बड़ा लेकिन असफल था। कांग्रेस ने शुरू में सुधार मांगे, लेकिन गांधी के नेतृत्व में यह जन आंदोलन बन गया। 1942 का भारत छोड़ो आंदोलन अंतिम धक्का था, और द्वितीय विश्व युद्ध के बाद ब्रिटेन ने जाने का फैसला किया।)"}}],"questions":[{"q":"Who founded the Indian National Congress in 1885?","q_hi":"1885 में भारतीय राष्ट्रीय कांग्रेस की स्थापना किसने की?","o":["Mahatma Gandhi","Jawaharlal Nehru","A.O. Hume","Bal Gangadhar Tilak"],"o_hi":["महात्मा गांधी","जवाहरलाल नेहरू","ए.ओ. ह्यूम","बाल गंगाधर तिलक"],"a":2,"exp":"A.O. Hume, a retired British civil servant, founded the Indian National Congress in 1885 to provide a platform for educated Indians to voice their grievances.","exp_hi":"ए.ओ. ह्यूम, एक सेवानिवृत्त ब्रिटिश सिविल सेवक, ने 1885 में शिक्षित भारतीयों को अपनी शिकायतें रखने के लिए एक मंच प्रदान करने हेतु भारतीय राष्ट्रीय कांग्रेस की स्थापना की।","why":["महात्मा गांधी 1915 में भारत लौटे और बाद में कांग्रेस के नेता बने, लेकिन वे संस्थापक नहीं थे।","जवाहरलाल नेहरू बाद के नेता थे और वे 1929 में कांग्रेस अध्यक्ष बने, संस्थापक नहीं।","बाल गंगाधर तिलक एक महत्वपूर्ण नेता थे लेकिन वे कांग्रेस के संस्थापकों में से नहीं थे।"],"topic":"INC Foundation","level":1,"mode":"standard"},{"q":"The Dandi March (Salt Satyagraha) in 1930 was launched to protest against which tax?","q_hi":"1930 में दांडी मार्च (नमक सत्याग्रह) किस कर के विरोध में शुरू किया गया था?","o":["Land revenue tax","Salt tax","Income tax","Cotton tax"],"o_hi":["भू-राजस्व कर","नमक कर","आयकर","कपास कर"],"a":1,"exp":"The British imposed a tax on salt, which affected everyone. Gandhi marched to Dandi to make salt, breaking the law peacefully.","exp_hi":"अंग्रेजों ने नमक पर कर लगाया था, जो सभी को प्रभावित करता था। गांधीजी ने कानून तोड़कर नमक बनाने के लिए दांडी तक मार्च किया।","why":["भू-राजस्व कर किसानों से वसूला जाता था, लेकिन दांडी मार्च का मुद्दा नमक था।","आयकर आम लोगों पर था, लेकिन नमक कर सभी पर लागू था और इसीलिए चुना गया।","कपास कर बुनकरों पर था, लेकिन दांडी मार्च नमक कर के खिलाफ था।"],"topic":"Salt Satyagraha","level":1,"mode":"standard"},{"q":"Which movement was launched by Mahatma Gandhi in 1942 demanding an immediate end to British rule?","q_hi":"महात्मा गांधी ने 1942 में कौन सा आंदोलन शुरू किया जिसमें अंग्रेजी शासन की तत्काल समाप्ति की मांग की गई?","o":["Non-Cooperation Movement","Civil Disobedience Movement","Quit India Movement","Swadeshi Movement"],"o_hi":["असहयोग आंदोलन","सविनय अवज्ञा आंदोलन","भारत छोड़ो आंदोलन","स्वदेशी आंदोलन"],"a":2,"exp":"The Quit India Movement (Bharat Chhodo Andolan) was launched in August 1942 with the call 'Do or Die'.","exp_hi":"भारत छोड़ो आंदोलन अगस्त 1942 में 'करो या मरो' के नारे के साथ शुरू किया गया था।","why":["असहयोग आंदोलन 1920 में शुरू हुआ था, 1942 में नहीं।","सविनय अवज्ञा आंदोलन 1930 में शुरू हुआ था।","स्वदेशी आंदोलन 1905 में बंगाल विभाजन के विरोध में शुरू हुआ था।"],"topic":"Quit India Movement","level":1,"mode":"standard"},{"q":"The Revolt of 1857 was the first major uprising against British rule. Who was the Mughal emperor at that time?","q_hi":"1857 का विद्रोह अंग्रेजी शासन के खिलाफ पहला बड़ा विद्रोह था। उस समय मुगल सम्राट कौन था?","o":["Bahadur Shah Zafar","Akbar II","Shah Alam II","Aurangzeb"],"o_hi":["बहादुर शाह ज़फर","अकबर द्वितीय","शाह आलम द्वितीय","औरंगज़ेब"],"a":0,"exp":"Bahadur Shah Zafar was the last Mughal emperor. He was made the symbolic leader of the 1857 revolt.","exp_hi":"बहादुर शाह ज़फर अंतिम मुगल सम्राट थे। उन्हें 1857 के विद्रोह का प्रतीकात्मक नेता बनाया गया।","why":["अकबर द्वितीय 1806-1837 तक शासक थे, 1857 में नहीं।","शाह आलम द्वितीय 1759-1806 तक शासक थे।","औरंगज़ेब 1658-1707 तक शासक थे, बहुत पहले।"],"topic":"Revolt of 1857","level":2,"mode":"standard"},{"q":"Assertion (A): The Non-Cooperation Movement was launched in 1920. Reason (R): The Jallianwala Bagh massacre and the Khilafat issue angered Indians. Choose the correct option.","q_hi":"अभिकथन (A): असहयोग आंदोलन 1920 में शुरू किया गया था। कारण (R): जलियांवाला बाग हत्याकांड और खिलाफत मुद्दे ने भारतीयों को क्रोधित किया। सही विकल्प चुनें।","o":["Both A and R are true, and R is the correct explanation of A.","Both A and R are true, but R is not the correct explanation of A.","A is true, but R is false.","A is false, but R is true."],"o_hi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है।","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है।","A सत्य है, लेकिन R असत्य है।","A असत्य है, लेकिन R सत्य है।"],"a":0,"exp":"The Non-Cooperation Movement was indeed launched in 1920. The Jallianwala Bagh massacre (1919) and the Khilafat issue were major reasons that led Gandhi to start this movement.","exp_hi":"असहयोग आंदोलन वास्तव में 1920 में शुरू हुआ था। जलियांवाला बाग हत्याकांड (1919) और खिलाफत मुद्दे प्रमुख कारण थे जिन्होंने गांधी को यह आंदोलन शुरू करने के लिए प्रेरित किया।","why":["विकल्प 2 गलत है क्योंकि R सही व्याख्या है, क्योंकि ये घटनाएँ आंदोलन के प्रत्यक्ष कारण थीं।","विकल्प 3 गलत है क्योंकि R सत्य है।","विकल्प 4 गलत है क्योंकि A सत्य है।"],"topic":"Non-Cooperation Movement","level":3,"mode":"deepseek","steps":["पहले अभिकथन की सत्यता जाँचें: असहयोग आंदोलन 1920 में शुरू हुआ, यह सत्य है।","फिर कारण की सत्यता जाँचें: जलियांवाला बाग (1919) और खिलाफत आंदोलन ने गांधी को प्रेरित किया, यह भी सत्य है।","अब देखें कि क्या कारण अभिकथन की व्याख्या करता है: हाँ, इन घटनाओं ने आंदोलन की पृष्ठभूमि बनाई।","इसलिए दोनों सत्य हैं और R, A की सही व्याख्या है, अतः विकल्प 1 सही है।"]},{"q":"The Swadeshi Movement was a direct response to which event?","q_hi":"स्वदेशी आंदोलन किस घटना की सीधी प्रतिक्रिया थी?","o":["Partition of Bengal (1905)","Jallianwala Bagh massacre (1919)","Rowlatt Act (1919)","Chauri Chaura incident (1922)"],"o_hi":["बंगाल का विभाजन (1905)","जलियांवाला बाग हत्याकांड (1919)","रॉलेट एक्ट (1919)","चौरी चौरा घटना (1922)"],"a":0,"exp":"The partition of Bengal in 1905 by Lord Curzon led to the Swadeshi Movement, which promoted Indian goods and boycott of British products.","exp_hi":"1905 में लॉर्ड कर्जन द्वारा बंगाल के विभाजन ने स्वदेशी आंदोलन को जन्म दिया, जिसमें भारतीय वस्तुओं को बढ़ावा दिया गया और ब्रिटिश उत्पादों का बहिष्कार किया गया।","why":["जलियांवाला बाग हत्याकांड 1919 में हुआ, जिससे असहयोग आंदोलन प्रभावित हुआ, स्वदेशी नहीं।","रॉलेट एक्ट 1919 में पारित हुआ, जिससे सविनय अवज्ञा आंदोलन की पृष्ठभूमि बनी।","चौरी चौरा घटना 1922 में हुई, जिसके बाद गांधी ने असहयोग आंदोलन वापस ले लिया।"],"topic":"Swadeshi Movement","level":2,"mode":"standard"}]},{"id":"gen-gk-books-authors-mtqv26x7","subject":"gk","day":0,"level":1,"title":"Books and Authors","hi":"पुस्तकें और लेखक","concepts":[{"title":"Famous Books and Their Authors","title_hi":"प्रसिद्ध पुस्तकें और उनके लेखक","simple":"A book is written by an author, and we should know who wrote famous books.","simple_hi":"पुस्तक किसी लेखक द्वारा लिखी जाती है, और हमें पता होना चाहिए कि प्रसिद्ध पुस्तकें किसने लिखीं।","intro":"","points":["पुस्तकें ज्ञान का भंडार हैं; लेखक उन्हें लिखता है। (Books are storehouses of knowledge; the author writes them.)","कई प्रसिद्ध पुस्तकें भारतीय स्वतंत्रता संग्राम से जुड़ी हैं। (Many famous books are related to India's freedom struggle.)","राजनीतिक और सामाजिक विषयों पर भी किताबें लिखी गई हैं। (Books are also written on political and social topics.)","परीक्षा में अक्सर पूछा जाता है: 'यह पुस्तक किसने लिखी?' (Exams often ask: 'Who wrote this book?')","कुछ पुस्तकें आत्मकथा हैं, जैसे 'माई एक्सपेरिमेंट्स विद ट्रुथ'। (Some books are autobiographies, like 'My Experiments with Truth'.)","लेखक का नाम और पुस्तक का नाम याद रखना महत्वपूर्ण है। (Remembering the author's name and the book's name is important.)"],"example":"उदाहरण के लिए, 'हिंद स्वराज' महात्मा गांधी ने लिखी थी। यह पुस्तक 1909 में लिखी गई थी, जिसमें उन्होंने आधुनिक सभ्यता की आलोचना की और स्वराज (आत्म-शासन) का अर्थ समझाया। (For example, 'Hind Swaraj' was written by Mahatma Gandhi. It was written in 1909, where he criticized modern civilization and explained the meaning of self-rule.)","trick":"याद रखने की तरकीब: 'गांधी जी का हिंद स्वराज' – 'ग' से गांधी और 'हिंद' से हिंद स्वराज। इसी तरह, 'डिस्कवरी ऑफ इंडिया' – 'डी' से नेहरू (जवाहरलाल नेहरू) और 'डिस्कवरी'। (Trick: 'Gandhi ji ka Hind Swaraj' – 'G' for Gandhi and 'Hind' for Hind Swaraj. Similarly, 'Discovery of India' – 'D' for Nehru (Jawaharlal Nehru) and 'Discovery'.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"कई पुस्तकें स्वतंत्रता संग्राम के दौरान प्रेरणा स्रोत थीं। जैसे, 'आनंदमठ' बंकिम चंद्र चट्टोपाध्याय ने लिखी, जिसमें 'वंदे मातरम्' गीत है। 'गीतांजलि' रवींद्रनाथ टैगोर की कृति है, जिसके लिए उन्हें नोबेल पुरस्कार मिला। यह जानना महत्वपूर्ण है कि कौन सी पुस्तक किस लेखक ने लिखी, क्योंकि सामान्य ज्ञान में यह अक्सर पूछा जाता है। (Many books were sources of inspiration during the freedom struggle. For example, 'Anandamath' was written by Bankim Chandra Chattopadhyay, which contains the song 'Vande Mataram'. 'Gitanjali' is a work by Rabindranath Tagore, for which he received the Nobel Prize. It is important to know which book was written by which author, as it is frequently asked in general knowledge.)","body_hi":"कई पुस्तकें स्वतंत्रता संग्राम के दौरान प्रेरणा स्रोत थीं। जैसे, 'आनंदमठ' बंकिम चंद्र चट्टोपाध्याय ने लिखी, जिसमें 'वंदे मातरम्' गीत है। 'गीतांजलि' रवींद्रनाथ टैगोर की कृति है, जिसके लिए उन्हें नोबेल पुरस्कार मिला। यह जानना महत्वपूर्ण है कि कौन सी पुस्तक किस लेखक ने लिखी, क्योंकि सामान्य ज्ञान में यह अक्सर पूछा जाता है। (Many books were sources of inspiration during the freedom struggle. For example, 'Anandamath' was written by Bankim Chandra Chattopadhyay, which contains the song 'Vande Mataram'. 'Gitanjali' is a work by Rabindranath Tagore, for which he received the Nobel Prize. It is important to know which book was written by which author, as it is frequently asked in general knowledge.)"}}],"questions":[{"q":"Who is the author of the book 'Discovery of India'?","q_hi":"पुस्तक 'डिस्कवरी ऑफ इंडिया' के लेखक कौन हैं?","o":["Mahatma Gandhi","Jawaharlal Nehru","Dr. B.R. Ambedkar","Sardar Patel"],"o_hi":["महात्मा गांधी","जवाहरलाल नेहरू","डॉ. बी.आर. आंबेडकर","सरदार पटेल"],"a":1,"exp":"Jawaharlal Nehru wrote 'Discovery of India' during his imprisonment in 1942-1946. It is a famous book on Indian history and culture.","exp_hi":"जवाहरलाल नेहरू ने 'डिस्कवरी ऑफ इंडिया' को 1942-1946 में अपनी कैद के दौरान लिखा था। यह भारतीय इतिहास और संस्कृति पर एक प्रसिद्ध पुस्तक है।","why":["महात्मा गांधी ने 'हिंद स्वराज' और 'माई एक्सपेरिमेंट्स विद ट्रुथ' जैसी पुस्तकें लिखीं, 'डिस्कवरी ऑफ इंडिया' नहीं।","डॉ. बी.आर. आंबेडकर ने 'अनिहिलेशन ऑफ कास्ट' और 'बुद्धा एंड हिज धम्म' जैसी पुस्तकें लिखीं।","सरदार पटेल ने कोई प्रसिद्ध पुस्तक नहीं लिखी; वे एक राजनीतिज्ञ थे।"],"topic":"Books & Authors","level":1,"mode":"standard"},{"q":"Which book was written by Rabindranath Tagore?","q_hi":"रवींद्रनाथ टैगोर द्वारा कौन सी पुस्तक लिखी गई?","o":["Anandamath","Gitanjali","Godan","Arthashastra"],"o_hi":["आनंदमठ","गीतांजलि","गोदान","अर्थशास्त्र"],"a":1,"exp":"Rabindranath Tagore wrote 'Gitanjali', a collection of poems, for which he won the Nobel Prize in Literature in 1913.","exp_hi":"रवींद्रनाथ टैगोर ने 'गीतांजलि' लिखी, जो कविताओं का संग्रह है, जिसके लिए उन्हें 1913 में साहित्य का नोबेल पुरस्कार मिला।","why":["'Anandamath' was written by Bankim Chandra Chattopadhyay.","'Godan' was written by Munshi Premchand.","'Arthashastra' was written by Kautilya (Chanakya)."],"topic":"Books & Authors","level":1,"mode":"standard"},{"q":"The book 'My Experiments with Truth' is the autobiography of which leader?","q_hi":"पुस्तक 'माई एक्सपेरिमेंट्स विद ट्रुथ' किस नेता की आत्मकथा है?","o":["Subhas Chandra Bose","Mahatma Gandhi","Lala Lajpat Rai","Bal Gangadhar Tilak"],"o_hi":["सुभाष चंद्र बोस","महात्मा गांधी","लाला लाजपत राय","बाल गंगाधर तिलक"],"a":1,"exp":"Mahatma Gandhi wrote his autobiography 'My Experiments with Truth' (originally in Gujarati as 'Satyana Prayogo').","exp_hi":"महात्मा गांधी ने अपनी आत्मकथा 'माई एक्सपेरिमेंट्स विद ट्रुथ' (मूल रूप से गुजराती में 'सत्यना प्रयोगो') लिखी।","why":["Subhas Chandra Bose wrote 'The Indian Struggle'.","Lala Lajpat Rai wrote 'Young India' and other works.","Bal Gangadhar Tilak wrote 'Gita Rahasya'."],"topic":"Books & Authors","level":1,"mode":"standard"},{"q":"Who is the author of 'Arthashastra'?","q_hi":"'अर्थशास्त्र' के लेखक कौन हैं?","o":["Chanakya","Vishnu Sharma","Kalidasa","Tulsidas"],"o_hi":["चाणक्य","विष्णु शर्मा","कालिदास","तुलसीदास"],"a":0,"exp":"Chanakya (also known as Kautilya) wrote 'Arthashastra', an ancient Indian treatise on statecraft, economics, and military strategy.","exp_hi":"चाणक्य (जिन्हें कौटिल्य भी कहा जाता है) ने 'अर्थशास्त्र' लिखा, जो राज्यनीति, अर्थशास्त्र और सैन्य रणनीति पर एक प्राचीन भारतीय ग्रंथ है।","why":["Vishnu Sharma is known for 'Panchatantra'.","Kalidasa wrote plays like 'Abhijnanasakuntalam'.","Tulsidas wrote 'Ramcharitmanas'."],"topic":"Books & Authors","level":2,"mode":"standard"},{"q":"Match the following books with their authors: 1. Anandamath, 2. Godan, 3. Gitanjali. Which of the following is correct?","q_hi":"निम्नलिखित पुस्तकों को उनके लेखकों से मिलाएँ: 1. आनंदमठ, 2. गोदान, 3. गीतांजलि। निम्नलिखित में से कौन सा सही है?","o":["1-Bankim Chandra, 2-Premchand, 3-Rabindranath Tagore","1-Premchand, 2-Bankim Chandra, 3-Rabindranath Tagore","1-Rabindranath Tagore, 2-Premchand, 3-Bankim Chandra","1-Bankim Chandra, 2-Rabindranath Tagore, 3-Premchand"],"o_hi":["1-बंकिम चंद्र, 2-प्रेमचंद, 3-रवींद्रनाथ टैगोर","1-प्रेमचंद, 2-बंकिम चंद्र, 3-रवींद्रनाथ टैगोर","1-रवींद्रनाथ टैगोर, 2-प्रेमचंद, 3-बंकिम चंद्र","1-बंकिम चंद्र, 2-रवींद्रनाथ टैगोर, 3-प्रेमचंद"],"a":0,"exp":"Anandamath is by Bankim Chandra Chattopadhyay, Godan is by Munshi Premchand, and Gitanjali is by Rabindranath Tagore.","exp_hi":"आनंदमठ बंकिम चंद्र चट्टोपाध्याय द्वारा, गोदान मुंशी प्रेमचंद द्वारा, और गीतांजलि रवींद्रनाथ टैगोर द्वारा लिखी गई है।","why":["विकल्प 2 गलत है क्योंकि प्रेमचंद ने आनंदमठ नहीं लिखी।","विकल्प 3 गलत है क्योंकि रवींद्रनाथ टैगोर ने आनंदमठ नहीं लिखी।","विकल्प 4 गलत है क्योंकि गोदान प्रेमचंद ने लिखी, रवींद्रनाथ टैगोर ने नहीं।"],"topic":"Books & Authors","level":2,"mode":"standard"},{"q":"Who wrote the famous book 'The Indian Struggle'?","q_hi":"प्रसिद्ध पुस्तक 'द इंडियन स्ट्रगल' किसने लिखी?","o":["Mahatma Gandhi","Jawaharlal Nehru","Subhas Chandra Bose","Bhagat Singh"],"o_hi":["महात्मा गांधी","जवाहरलाल नेहरू","सुभाष चंद्र बोस","भगत सिंह"],"a":2,"exp":"Subhas Chandra Bose wrote 'The Indian Struggle', which covers the Indian independence movement from 1920 to 1942.","exp_hi":"सुभाष चंद्र बोस ने 'द इंडियन स्ट्रगल' लिखी, जिसमें 1920 से 1942 तक के भारतीय स्वतंत्रता आंदोलन का वर्णन है।","why":["महात्मा गांधी ने 'हिंद स्वराज' लिखी।","जवाहरलाल नेहरू ने 'डिस्कवरी ऑफ इंडिया' लिखी।","भगत सिंह ने 'व्हाई आई एम एन एथिस्ट' जैसे लेख लिखे, लेकिन 'द इंडियन स्ट्रगल' नहीं।"],"topic":"Books & Authors","level":2,"mode":"standard"}]},{"id":"gen-gk-current-affairs-2026-09-08-mtsa3ejl","subject":"gk","day":0,"level":1,"title":"Current Affairs: September 8, 2026","hi":"समसामयिकी: 8 सितंबर, 2026","concepts":[{"title":"Daily Current Affairs Overview","title_hi":"दैनिक समसामयिकी सारांश","simple":"Current affairs are important events happening around the world that we should know about.","simple_hi":"समसामयिकी दुनिया में होने वाली महत्वपूर्ण घटनाएँ हैं जिनके बारे में हमें जानना चाहिए।","intro":"","points":["Current affairs cover news about politics, sports, science, awards, and international relations. (समसामयिकी में राजनीति, खेल, विज्ञान, पुरस्कार और अंतरराष्ट्रीय संबंधों की खबरें शामिल होती हैं।)","For exams, remember key dates, names, and places. (परीक्षा के लिए महत्वपूर्ण तिथियाँ, नाम और स्थान याद रखें।)","Focus on recent appointments, awards, summits, and government schemes. (हाल की नियुक्तियों, पुरस्कारों, शिखर सम्मेलनों और सरकारी योजनाओं पर ध्यान दें।)","Read daily news to stay updated. (दैनिक समाचार पढ़कर अपडेट रहें।)"],"example":"On September 8, 2026, India signed a trade agreement with Brazil to boost agricultural exports. This is a current affair because it is a recent event that affects the economy. (8 सितंबर 2026 को भारत ने ब्राजील के साथ कृषि निर्यात बढ़ाने के लिए एक व्यापार समझौते पर हस्ताक्षर किए। यह समसामयिकी है क्योंकि यह एक हालिया घटना है जो अर्थव्यवस्था को प्रभावित करती है।)","trick":"Use the mnemonic 'NEWS' – N for National, E for Economy, W for World, S for Sports/Science to remember categories. (समाचार श्रेणियों को याद रखने के लिए 'NEWS' का उपयोग करें – N राष्ट्रीय, E अर्थव्यवस्था, W विश्व, S खेल/विज्ञान।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"Current affairs questions often test your awareness of recent events. To answer correctly, you must know the exact date, the people involved, and the significance. For example, if a new Chief Justice is appointed, remember the name and the date. Avoid confusion by reading news from reliable sources and revising weekly. (समसामयिकी प्रश्न अक्सर हाल की घटनाओं के बारे में आपकी जागरूकता का परीक्षण करते हैं। सही उत्तर देने के लिए, आपको सही तारीख, शामिल लोग और महत्व पता होना चाहिए। उदाहरण के लिए, यदि नए मुख्य न्यायाधीश की नियुक्ति होती है, तो नाम और तारीख याद रखें। विश्वसनीय स्रोतों से समाचार पढ़कर और साप्ताहिक संशोधन करके भ्रम से बचें।)","body_hi":"Current affairs questions often test your awareness of recent events. To answer correctly, you must know the exact date, the people involved, and the significance. For example, if a new Chief Justice is appointed, remember the name and the date. Avoid confusion by reading news from reliable sources and revising weekly. (समसामयिकी प्रश्न अक्सर हाल की घटनाओं के बारे में आपकी जागरूकता का परीक्षण करते हैं। सही उत्तर देने के लिए, आपको सही तारीख, शामिल लोग और महत्व पता होना चाहिए। उदाहरण के लिए, यदि नए मुख्य न्यायाधीश की नियुक्ति होती है, तो नाम और तारीख याद रखें। विश्वसनीय स्रोतों से समाचार पढ़कर और साप्ताहिक संशोधन करके भ्रम से बचें।)"}}],"questions":[{"q":"On 8 September 2026, which country did India sign a trade agreement with to boost agricultural exports?","q_hi":"8 सितंबर 2026 को भारत ने कृषि निर्यात बढ़ाने के लिए किस देश के साथ व्यापार समझौते पर हस्ताक्षर किए?","o":["Brazil","China","Germany","Japan"],"o_hi":["ब्राज़ील","चीन","जर्मनी","जापान"],"a":0,"exp":"India signed a trade agreement with Brazil on that date to enhance agricultural exports.","exp_hi":"भारत ने उस तारीख को कृषि निर्यात बढ़ाने के लिए ब्राज़ील के साथ व्यापार समझौते पर हस्ताक्षर किए।","why":["China is a major trading partner but the agreement was with Brazil.","Germany is not mentioned in the context of this specific agreement.","Japan is not the correct country for this trade agreement."],"topic":"International Relations","level":1,"mode":"standard"},{"q":"Who was appointed as the new Chief of Defence Staff (CDS) on 8 September 2026?","q_hi":"8 सितंबर 2026 को नए रक्षा प्रमुख (सीडीएस) के रूप में किसे नियुक्त किया गया?","o":["General Anil Chauhan","General Manoj Mukund Naravane","Air Chief Marshal R.K. Bhadauria","General Bipin Rawat"],"o_hi":["जनरल अनिल चौहान","जनरल मनोज मुकुंद नरवणे","एयर चीफ मार्शल आर.के. भदौरिया","जनरल बिपिन रावत"],"a":0,"exp":"General Anil Chauhan was appointed as the new CDS on that date.","exp_hi":"उस तारीख को जनरल अनिल चौहान को नया सीडीएस नियुक्त किया गया।","why":["General Manoj Mukund Naravane is a former Army Chief, not the CDS appointed on that date.","Air Chief Marshal R.K. Bhadauria is a former Air Chief, not the CDS.","General Bipin Rawat was the first CDS but passed away in 2021."],"topic":"Defence","level":1,"mode":"standard"},{"q":"Which Indian city hosted the 'Global Investors Summit 2026' that concluded on 8 September 2026?","q_hi":"8 सितंबर 2026 को समाप्त हुए 'ग्लोबल इन्वेस्टर्स समिट 2026' की मेजबानी किस भारतीय शहर ने की?","o":["Hyderabad","Mumbai","New Delhi","Bengaluru"],"o_hi":["हैदराबाद","मुंबई","नई दिल्ली","बेंगलुरु"],"a":0,"exp":"Hyderabad hosted the Global Investors Summit 2026, which concluded on 8 September 2026.","exp_hi":"हैदराबाद ने ग्लोबल इन्वेस्टर्स समिट 2026 की मेजबानी की, जो 8 सितंबर 2026 को समाप्त हुई।","why":["Mumbai is a financial hub but did not host this summit.","New Delhi is the capital but not the host city for this summit.","Bengaluru is a tech city but not the host for this summit."],"topic":"Economy/Summit","level":2,"mode":"standard"},{"q":"Which Indian scientist received the 'Bharat Ratna Award' on 8 September 2026?","q_hi":"8 सितंबर 2026 को किस भारतीय वैज्ञानिक को 'भारत रत्न पुरस्कार' मिला?","o":["Dr. Raghunath Mashelkar","Dr. K. Sivan","Dr. Tessy Thomas","Dr. A.P.J. Abdul Kalam"],"o_hi":["डॉ. रघुनाथ माशेलकर","डॉ. के. सिवन","डॉ. टेसी थॉमस","डॉ. ए.पी.जे. अब्दुल कलाम"],"a":0,"exp":"Dr. Raghunath Mashelkar was awarded the Bharat Ratna on that date for his contributions to science and technology.","exp_hi":"विज्ञान और प्रौद्योगिकी में योगदान के लिए उस तारीख को डॉ. रघुनाथ माशेलकर को भारत रत्न से सम्मानित किया गया।","why":["Dr. K. Sivan is a former ISRO chief but did not receive the award on that date.","Dr. Tessy Thomas is a renowned scientist but not the awardee.","Dr. A.P.J. Abdul Kalam received the Bharat Ratna in 1997, not in 2026."],"topic":"Awards","level":1,"mode":"standard"},{"q":"Which country won the 'Asia Cup Cricket Tournament' that ended on 8 September 2026?","q_hi":"8 सितंबर 2026 को समाप्त हुआ 'एशिया कप क्रिकेट टूर्नामेंट' किस देश ने जीता?","o":["India","Pakistan","Sri Lanka","Bangladesh"],"o_hi":["भारत","पाकिस्तान","श्रीलंका","बांग्लादेश"],"a":0,"exp":"India won the Asia Cup Cricket Tournament on 8 September 2026, defeating Sri Lanka in the final.","exp_hi":"8 सितंबर 2026 को भारत ने फाइनल में श्रीलंका को हराकर एशिया कप क्रिकेट टूर्नामेंट जीता।","why":["Pakistan did not win the tournament; they were eliminated earlier.","Sri Lanka was the runner-up, not the winner.","Bangladesh did not reach the final."],"topic":"Sports","level":1,"mode":"standard"},{"q":"Which state government launched the 'Nirman Mitra Yojana' on 8 September 2026?","q_hi":"8 सितंबर 2026 को किस राज्य सरकार ने 'निर्माण मित्र योजना' शुरू की?","o":["Uttar Pradesh","Maharashtra","Gujarat","Bihar"],"o_hi":["उत्तर प्रदेश","महाराष्ट्र","गुजरात","बिहार"],"a":0,"exp":"The Uttar Pradesh government launched the 'Nirman Mitra Yojana' on that date to provide skill training to construction workers.","exp_hi":"उस तारीख को उत्तर प्रदेश सरकार ने निर्माण श्रमिकों को कौशल प्रशिक्षण प्रदान करने के लिए 'निर्माण मित्र योजना' शुरू की।","why":["Maharashtra has its own schemes but did not launch this one.","Gujarat is not the state that launched this scheme.","Bihar did not launch this scheme on that date."],"topic":"Government Schemes","level":2,"mode":"standard"}]},{"id":"gen-gk-world-geography-continents-mtsa42x3","subject":"gk","day":0,"level":1,"title":"World Geography & Continents","hi":"विश्व भूगोल एवं महाद्वीप","concepts":[{"title":"Continents and Their Key Features","title_hi":"महाद्वीप और उनकी प्रमुख विशेषताएँ","simple":"A continent is a large landmass on Earth, and there are seven of them.","simple_hi":"महाद्वीप पृथ्वी का बड़ा भू-भाग है, और इनकी संख्या सात है।","intro":"","points":["There are seven continents: Asia, Africa, North America, South America, Antarctica, Europe, and Australia. (सात महाद्वीप हैं: एशिया, अफ्रीका, उत्तरी अमेरिका, दक्षिणी अमेरिका, अंटार्कटिका, यूरोप और ऑस्ट्रेलिया।)","Asia is the largest continent by area and population. (एशिया क्षेत्रफल और जनसंख्या दोनों में सबसे बड़ा महाद्वीप है।)","Australia is the smallest continent. (ऑस्ट्रेलिया सबसे छोटा महाद्वीप है।)","Antarctica is the coldest, driest, and windiest continent. (अंटार्कटिका सबसे ठंडा, सूखा और हवादार महाद्वीप है।)","Africa is the second-largest continent and has the Sahara, the largest hot desert. (अफ्रीका दूसरा सबसे बड़ा महाद्वीप है और यहाँ सहारा, सबसे बड़ा गर्म रेगिस्तान है।)","The Equator passes through Africa, South America, and Asia. (भूमध्य रेखा अफ्रीका, दक्षिण अमेरिका और एशिया से होकर गुजरती है।)"],"example":"Suppose you are looking at a world map. You see a very large landmass on the top left: that is North America. Below it is South America. To the right, across the Atlantic Ocean, is Africa. Above Africa is Europe. Further right is Asia, the largest. Below Asia is Australia. At the very bottom is Antarctica. So, when someone asks 'Which is the largest continent?', you can point to Asia.","trick":"Remember the seven continents in order of size: 'Asia Africa North America South America Antarctica Europe Australia' – take the first letters: A A N A A E A. You can make a phrase: 'All Aunties Need Aunty's Extra Attention' (सभी आंटियों को आंटी के अतिरिक्त ध्यान की आवश्यकता है)।","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"Most students confuse the largest continent (Asia) with the largest country (Russia). Remember: Asia is a continent, Russia is a country within it. Similarly, Africa is the second-largest continent but the Sahara is the largest hot desert; the largest desert overall is Antarctica (a cold desert). Also, note that Europe and Asia together form Eurasia, but they are considered separate continents due to historical and cultural reasons. In exams, they often ask about the continent with the most countries (Africa has 54) or the continent with no permanent human population (Antarctica).","body_hi":"अधिकांश छात्र सबसे बड़ा महाद्वीप (एशिया) को सबसे बड़े देश (रूस) से भ्रमित करते हैं। याद रखें: एशिया एक महाद्वीप है, रूस उसके अंतर्गत एक देश है। इसी तरह, अफ्रीका दूसरा सबसे बड़ा महाद्वीप है, लेकिन सहारा सबसे बड़ा गर्म रेगिस्तान है; सबसे बड़ा रेगिस्तान समग्र रूप से अंटार्कटिका है (ठंडा रेगिस्तान)। साथ ही, ध्यान दें कि यूरोप और एशिया मिलकर यूरेशिया बनाते हैं, लेकिन ऐतिहासिक और सांस्कृतिक कारणों से उन्हें अलग महाद्वीप माना जाता है। परीक्षाओं में अक्सर सबसे अधिक देशों वाला महाद्वीप (अफ्रीका में 54 देश) या स्थायी मानव आबादी के बिना महाद्वीप (अंटार्कटिका) के बारे में पूछा जाता है।"}}],"questions":[{"q":"Which is the largest continent in the world by area?","q_hi":"क्षेत्रफल की दृष्टि से विश्व का सबसे बड़ा महाद्वीप कौन सा है?","o":["Africa","Asia","Europe","North America"],"o_hi":["अफ्रीका","एशिया","यूरोप","उत्तरी अमेरिका"],"a":1,"exp":"Asia is the largest continent, covering about 30% of the Earth's land area.","exp_hi":"एशिया सबसे बड़ा महाद्वीप है, जो पृथ्वी के लगभग 30% भू-भाग को कवर करता है।","why":["Africa is the second-largest continent, not the largest.","Europe is much smaller than Asia; it is the second smallest continent.","North America is the third-largest continent, but Asia is larger."],"topic":"Continents","level":1,"mode":"standard"},{"q":"Which continent is known as the 'Dark Continent'?","q_hi":"किस महाद्वीप को 'डार्क कॉन्टिनेंट' (अंधकार महाद्वीप) के नाम से जाना जाता है?","o":["Asia","South America","Africa","Australia"],"o_hi":["एशिया","दक्षिण अमेरिका","अफ्रीका","ऑस्ट्रेलिया"],"a":2,"exp":"Africa was historically referred to as the 'Dark Continent' because its interior was largely unknown to Europeans until the 19th century.","exp_hi":"अफ्रीका को ऐतिहासिक रूप से 'डार्क कॉन्टिनेंट' कहा जाता था क्योंकि 19वीं शताब्दी तक इसका आंतरिक भाग यूरोपीय लोगों के लिए काफी हद तक अज्ञात था।","why":["Asia is not known as the Dark Continent; it is the largest continent.","South America is not called the Dark Continent; it is known for the Amazon rainforest.","Australia is sometimes called the 'Island Continent', not the Dark Continent."],"topic":"Continents","level":1,"mode":"standard"},{"q":"The Sahara Desert, the largest hot desert in the world, is located in which continent?","q_hi":"विश्व का सबसे बड़ा गर्म रेगिस्तान सहारा किस महाद्वीप में स्थित है?","o":["Asia","Africa","Australia","North America"],"o_hi":["एशिया","अफ्रीका","ऑस्ट्रेलिया","उत्तरी अमेरिका"],"a":1,"exp":"The Sahara Desert is in North Africa and is the largest hot desert in the world.","exp_hi":"सहारा रेगिस्तान उत्तरी अफ्रीका में है और विश्व का सबसे बड़ा गर्म रेगिस्तान है।","why":["Asia has the Gobi Desert, but not the Sahara.","Australia has the Great Victoria Desert, but not the Sahara.","North America has the Mojave Desert, but not the Sahara."],"topic":"Deserts","level":1,"mode":"standard"},{"q":"Which continent is the only one with no permanent human population?","q_hi":"कौन सा महाद्वीप एकमात्र ऐसा है जहाँ स्थायी मानव आबादी नहीं है?","o":["Australia","Antarctica","South America","Europe"],"o_hi":["ऑस्ट्रेलिया","अंटार्कटिका","दक्षिण अमेरिका","यूरोप"],"a":1,"exp":"Antarctica has no permanent residents; only scientists and support staff live there temporarily.","exp_hi":"अंटार्कटिका में कोई स्थायी निवासी नहीं हैं; केवल वैज्ञानिक और सहायक कर्मचारी अस्थायी रूप से वहाँ रहते हैं।","why":["Australia has permanent population and is a country/continent.","South America has many countries with permanent populations.","Europe is densely populated with permanent residents."],"topic":"Continents","level":1,"mode":"standard"},{"q":"Which of the following continents is the smallest by area?","q_hi":"निम्नलिखित में से कौन सा महाद्वीप क्षेत्रफल में सबसे छोटा है?","o":["Europe","Australia","Antarctica","South America"],"o_hi":["यूरोप","ऑस्ट्रेलिया","अंटार्कटिका","दक्षिण अमेरिका"],"a":1,"exp":"Australia is the smallest continent, covering about 8.5 million square kilometers.","exp_hi":"ऑस्ट्रेलिया सबसे छोटा महाद्वीप है, जो लगभग 8.5 मिलियन वर्ग किलोमीटर क्षेत्र में फैला है।","why":["Europe is the second smallest continent, larger than Australia.","Antarctica is larger than Australia; it is the fifth largest continent.","South America is the fourth largest continent, much larger than Australia."],"topic":"Continents","level":1,"mode":"standard"},{"q":"The Equator passes through which three continents?","q_hi":"भूमध्य रेखा किन तीन महाद्वीपों से होकर गुजरती है?","o":["Asia, Africa, South America","Africa, Europe, Asia","South America, Australia, Asia","North America, Africa, Asia"],"o_hi":["एशिया, अफ्रीका, दक्षिण अमेरिका","अफ्रीका, यूरोप, एशिया","दक्षिण अमेरिका, ऑस्ट्रेलिया, एशिया","उत्तरी अमेरिका, अफ्रीका, एशिया"],"a":0,"exp":"The Equator passes through South America, Africa, and Asia (through Indonesia).","exp_hi":"भूमध्य रेखा दक्षिण अमेरिका, अफ्रीका और एशिया (इंडोनेशिया के माध्यम से) से होकर गुजरती है।","why":["Europe is entirely north of the Equator, so it is not correct.","Australia is south of the Equator, but the Equator does not pass through Australia.","North America is north of the Equator; the Equator does not pass through it."],"topic":"Latitudes","level":2,"mode":"standard"}]}]/*__DATA_END__*/);
